window.STUDY_DATA = {"groups": {"w1": {"name": "Week 1", "title": "Usability & design", "description": "Goals, design principles, human error and user experience.", "kind": "lecture"}, "w2": {"name": "Week 2", "title": "Humans & cognition", "description": "Mental models, action cycle, perception, attention and memory.", "kind": "lecture"}, "w3": {"name": "Week 3", "title": "Input & mobile", "description": "Devices, sensors, virtual reality and mobile constraints.", "kind": "lecture"}, "w4": {"name": "Week 4", "title": "Requirements & research", "description": "Users, research methods, use cases and task models.", "kind": "lecture"}, "project": {"name": "Project", "title": "Assignment & your idea", "description": "The walkthrough brief and your proposed nutrition companion.", "kind": "project"}, "extra": {"name": "Other professor", "title": "Supplemental midterm practice", "description": "Topics from the photos; not evidence of Andriy’s exam coverage.", "kind": "supplemental"}, "context": {"name": "Background", "title": "Slides marked “Not on test”", "description": "Optional context from Week 2, excluded from lecture drills.", "kind": "background"}}, "questions": [{"id": "w1-m01", "type": "mcq", "group": "w1", "prompt": "Which sequence best represents iterative interface design?", "options": ["Design, prototype, evaluate, revise", "Specify, code, release, stop", "Choose colours, advertise, release, survey", "Train users, release, then gather requirements"], "correct": 0, "explanation": "Evaluation informs revisions throughout design.", "source": "Week 1 · PDF pp. 5–6", "topic": "Design process", "origin": "lecture", "level": "concept"}, {"id": "w1-m02", "type": "mcq", "group": "w1", "prompt": "A system supports every needed function, but users cannot operate it. Which distinction matters?", "options": ["Utility versus usability", "Safety versus hardware speed", "Memorability versus data storage", "UX versus screen resolution"], "correct": 0, "explanation": "A function can exist without being usable.", "source": "Week 1 · PDF pp. 73, 78", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-m03", "type": "mcq", "group": "w1", "prompt": "Users finish a task correctly but spend unnecessary time doing it. Which goal needs work?", "options": ["Efficiency", "Utility", "Effectiveness", "Memorability"], "correct": 0, "explanation": "Efficiency concerns the effort and time required for successful use.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-m04", "type": "mcq", "group": "w1", "prompt": "Which measure most directly concerns effectiveness?", "options": ["Whether the intended task is completed correctly", "How attractive the interface looks", "How many optional features exist", "How recently the user last visited"], "correct": 0, "explanation": "Effectiveness concerns achieving the intended goal.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals", "origin": "lecture", "level": "concept"}, {"id": "w1-m05", "type": "mcq", "group": "w1", "prompt": "An occasional user returns after months and still knows how to proceed. Which goal is supported?", "options": ["Memorability", "Utility", "System throughput", "Novelty"], "correct": 0, "explanation": "Memorability concerns remembering how to use a system after time away.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-m06", "type": "mcq", "group": "w1", "prompt": "A first-time user learns the booking process quickly. Which goal is illustrated?", "options": ["Learnability", "Memorability", "Raw performance", "Feature completeness"], "correct": 0, "explanation": "Learnability concerns acquiring the ability to use the system.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-m07", "type": "mcq", "group": "w1", "prompt": "A payment tool cannot issue refunds, though users need them. Which goal is lacking?", "options": ["Utility", "Memorability", "Visual similarity", "Feedback latency"], "correct": 0, "explanation": "Utility concerns whether needed functions are available.", "source": "Week 1 · PDF p. 73", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-m08", "type": "mcq", "group": "w1", "prompt": "Why should designers account for distraction and fatigue?", "options": ["They are predictable human limitations that design must accommodate", "They make user research unnecessary", "They can always be eliminated by training", "They prove that users are responsible for all failures"], "correct": 0, "explanation": "The lecture challenges blaming users for failures encouraged by design.", "source": "Week 1 · PDF pp. 42–43, 59", "topic": "Human error", "origin": "lecture", "level": "concept"}, {"id": "w1-m09", "type": "mcq", "group": "w1", "prompt": "Who is central to user-centred design?", "options": ["Actual users and evidence about their needs", "Only the most experienced developer", "Only the purchasing department", "Only the visual designer’s intuition"], "correct": 0, "explanation": "User-centred design incorporates users into development.", "source": "Week 1 · PDF p. 63", "topic": "Design process", "origin": "lecture", "level": "concept"}, {"id": "w1-m10", "type": "mcq", "group": "w1", "prompt": "What is an affordance?", "options": ["A possible action arising from an object–person relationship", "A decorative theme shared across screens", "A message displayed after an error", "A mandatory sequence of menu items"], "correct": 0, "explanation": "A handle affords grasping; a knob affords turning.", "source": "Week 1 · PDF p. 80", "topic": "Design principles", "origin": "lecture", "level": "concept"}, {"id": "w1-m11", "type": "mcq", "group": "w1", "prompt": "A graphical button looks clickable because users recognize its styling. What best describes this?", "options": ["A perceived affordance using learned conventions", "A physical spring-return mechanism", "A system performance requirement", "A guarantee of universal cultural understanding"], "correct": 0, "explanation": "Virtual interfaces often rely on perceived affordances and conventions.", "source": "Week 1 · PDF p. 81", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-m12", "type": "mcq", "group": "w1", "prompt": "Stove controls arranged to match burner positions mainly improve what?", "options": ["Mapping", "User anonymity", "Memory capacity", "Feature count"], "correct": 0, "explanation": "Spatial correspondence clarifies which control affects which burner.", "source": "Week 1 · PDF p. 87", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-m13", "type": "mcq", "group": "w1", "prompt": "After Save, a visible message says “Saved.” Which principle is demonstrated?", "options": ["Feedback", "Utility", "Physical affordance", "Cultural localization"], "correct": 0, "explanation": "Feedback communicates the result of an action.", "source": "Week 1 · PDF p. 88", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-m14", "type": "mcq", "group": "w1", "prompt": "A crucial function is hidden behind an unfamiliar icon. Which issue is most direct?", "options": ["Visibility", "Calorie accuracy", "Motor neutral position", "Power consumption"], "correct": 0, "explanation": "Users need to discover relevant controls and actions.", "source": "Week 1 · PDF p. 91", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-m15", "type": "mcq", "group": "w1", "prompt": "Disabling an impossible date choice is an example of what?", "options": ["A constraint", "A positive transfer effect", "A colour model", "A conceptual mismatch alone"], "correct": 0, "explanation": "Constraints restrict actions and can prevent invalid choices.", "source": "Week 1 · PDF p. 96", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-m16", "type": "mcq", "group": "w1", "prompt": "Why use similar labels and behaviours for similar tasks?", "options": ["To reduce learning demands through consistency", "To make every function visually identical", "To remove the need for feedback", "To prevent experienced users using shortcuts"], "correct": 0, "explanation": "Consistency supports learning and predictable use.", "source": "Week 1 · PDF pp. 97–98", "topic": "Design principles", "origin": "lecture", "level": "concept"}, {"id": "w1-m17", "type": "mcq", "group": "w1", "prompt": "A familiar shortcut performs the same action in a new editor. What is this?", "options": ["Positive transfer", "Negative transfer", "Change blindness", "A physical constraint"], "correct": 0, "explanation": "Prior experience helps with the current task.", "source": "Week 1 · PDF pp. 92–93; Week 2 p. 46", "topic": "Transfer", "origin": "lecture", "level": "application"}, {"id": "w1-m18", "type": "mcq", "group": "w1", "prompt": "A familiar aircraft-control location triggers a different action in another aircraft. What risk does this illustrate?", "options": ["Negative transfer", "Improved recognition", "Successful annotation", "Increased utility"], "correct": 0, "explanation": "An old learned response can interfere in a new context.", "source": "Week 1 · PDF pp. 50–51, 92", "topic": "Transfer", "origin": "lecture", "level": "application"}, {"id": "w1-m19", "type": "mcq", "group": "w1", "prompt": "Which statement best describes user experience?", "options": ["It includes feelings and the broader interaction with a product and service", "It is identical to the number of features", "It can be guaranteed for every user by selecting colours", "It concerns only task-completion speed"], "correct": 0, "explanation": "UX includes satisfaction, emotion, and the wider experience.", "source": "Week 1 · PDF pp. 70–71, 76", "topic": "User experience", "origin": "lecture", "level": "concept"}, {"id": "w1-m20", "type": "mcq", "group": "w1", "prompt": "Which is a desirable experience goal named in the lecture?", "options": ["Engagement", "Patronizing behaviour", "Frustration", "Boredom"], "correct": 0, "explanation": "Engagement is among the desirable UX goals.", "source": "Week 1 · PDF p. 76", "topic": "User experience", "origin": "lecture", "level": "concept"}, {"id": "w1-m21", "type": "mcq", "group": "w1", "prompt": "Which kind of rule has high authority and limited application?", "options": ["A standard", "A broad design principle", "An informal suggestion", "A designer’s preference"], "correct": 0, "explanation": "Standards are specific and authoritative within their scope.", "source": "Week 1 · PDF p. 77", "topic": "Rules", "origin": "lecture", "level": "concept"}, {"id": "w1-m22", "type": "mcq", "group": "w1", "prompt": "Why can a learned symbol be confusing across cultures?", "options": ["Its meaning may depend on conventions and prior experience", "Every symbol has a universal natural meaning", "Culture affects only font size", "All mappings are physical affordances"], "correct": 0, "explanation": "Cultural associations should not be assumed to be universal.", "source": "Week 1 · PDF p. 94", "topic": "Individual differences", "origin": "lecture", "level": "concept"}, {"id": "w1-m23", "type": "mcq", "group": "w1", "prompt": "An error message says only “Something went wrong.” What is the main weakness?", "options": ["It does not help users understand or recover from the failure", "It provides too many task-specific instructions", "It establishes a natural control mapping", "It prevents the failed action before it happens"], "correct": 0, "explanation": "Feedback should explain what happened in understandable terms.", "source": "Week 1 · PDF pp. 89–90", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-m24", "type": "mcq", "group": "w1", "prompt": "Which belongs to the UI beyond visual styling?", "options": ["Navigation, control behaviour and the conceptual model", "Only advertising copy", "Only database indexing", "Only the device’s processor"], "correct": 0, "explanation": "The UI includes all aspects that influence interaction.", "source": "Week 1 · PDF p. 69", "topic": "UI scope", "origin": "lecture", "level": "concept"}, {"id": "w1-m25", "type": "mcq", "group": "w1", "prompt": "Why might matching every app icon’s appearance hurt usability?", "options": ["Different functions can become hard to distinguish", "Consistency always requires identical icons", "Recognition works only with words", "Users cannot learn icon meanings"], "correct": 0, "explanation": "Consistency must preserve meaningful distinctions.", "source": "Week 1 · PDF p. 100", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w2-m01", "type": "mcq", "group": "w2", "prompt": "What is a mental model?", "options": ["A user’s internal understanding of how something works", "A complete technical specification", "A guaranteed accurate system diagram", "A fixed set of screen dimensions"], "correct": 0, "explanation": "Mental models help people predict system behaviour but may be wrong.", "source": "Week 2 · PDF pp. 8–11, 19", "topic": "Mental models", "origin": "lecture", "level": "concept"}, {"id": "w2-m02", "type": "mcq", "group": "w2", "prompt": "Through what does the designer mainly communicate the intended model?", "options": ["The system image: appearance, labels and behaviour", "Unseen implementation comments", "The CPU instruction set", "A persona’s fictional name alone"], "correct": 0, "explanation": "Users infer how a system works from what they encounter.", "source": "Week 2 · PDF pp. 15–17, 21", "topic": "Mental models", "origin": "lecture", "level": "concept"}, {"id": "w2-m03", "type": "mcq", "group": "w2", "prompt": "Which ordering matches Norman’s action cycle?", "options": ["Goal → intention → sequence → execute → perceive → interpret → evaluate", "Goal → execute → intention → evaluate → perceive → plan → interpret", "Perceive → evaluate → goal → interpret → act → plan → intend", "Intention → evaluate → act → goal → perceive → sequence → interpret"], "correct": 0, "explanation": "The cycle connects goal formation, execution, and evaluation.", "source": "Week 2 · PDF p. 13", "topic": "Action cycle", "origin": "lecture", "level": "concept"}, {"id": "w2-m04", "type": "mcq", "group": "w2", "prompt": "A user knows the goal but cannot discover the needed control. Which gulf is involved?", "options": ["Gulf of execution", "Gulf of evaluation", "A sensory-memory gulf", "A colour-space gulf"], "correct": 0, "explanation": "The execution gulf concerns translating intentions into available actions.", "source": "Week 2 · PDF p. 14", "topic": "Action cycle", "origin": "lecture", "level": "application"}, {"id": "w2-m05", "type": "mcq", "group": "w2", "prompt": "A user clicks Submit but cannot tell whether it worked. Which gulf is involved?", "options": ["Gulf of evaluation", "Gulf of execution", "Positive transfer", "Near transfer"], "correct": 0, "explanation": "The evaluation gulf concerns understanding the system state and result.", "source": "Week 2 · PDF p. 14", "topic": "Action cycle", "origin": "lecture", "level": "application"}, {"id": "w2-m06", "type": "mcq", "group": "w2", "prompt": "Noticing the words “Booking confirmed” is primarily which stage?", "options": ["Perceiving the state", "Forming the intention", "Evaluating against the goal", "Planning the action sequence"], "correct": 0, "explanation": "Perception is noticing the information; interpretation gives it meaning.", "source": "Week 2 · PDF p. 13", "topic": "Action cycle", "origin": "lecture", "level": "application"}, {"id": "w2-m07", "type": "mcq", "group": "w2", "prompt": "Deciding that a confirmed appointment matches the requested time is which stage?", "options": ["Evaluating against the goal", "Executing the sequence", "Perceiving pixels", "Forming an initial intention"], "correct": 0, "explanation": "Evaluation compares the understood outcome with the goal.", "source": "Week 2 · PDF p. 13", "topic": "Action cycle", "origin": "lecture", "level": "application"}, {"id": "w2-m08", "type": "mcq", "group": "w2", "prompt": "A visible checklist replaces remembering unfinished steps. What benefit does it provide?", "options": ["Externalizing information to reduce memory load", "Eliminating all cognitive processing", "Changing a binary input to analog", "Removing the need for a goal"], "correct": 0, "explanation": "External representations support cognition.", "source": "Week 2 · PDF pp. 26–28", "topic": "External cognition", "origin": "lecture", "level": "application"}, {"id": "w2-m09", "type": "mcq", "group": "w2", "prompt": "Crossing completed items off a list is what?", "options": ["Annotation", "Cognitive tracing", "Negative transfer", "Controlled polling"], "correct": 0, "explanation": "Annotation modifies an existing representation by adding marks.", "source": "Week 2 · PDF p. 29", "topic": "External cognition", "origin": "lecture", "level": "application"}, {"id": "w2-m10", "type": "mcq", "group": "w2", "prompt": "Rearranging letter tiles to explore words is what?", "options": ["Cognitive tracing", "A state transition alone", "Factual interviewing", "Photopic adaptation"], "correct": 0, "explanation": "Cognitive tracing manipulates external items into different arrangements.", "source": "Week 2 · PDF pp. 29–35", "topic": "External cognition", "origin": "lecture", "level": "application"}, {"id": "w2-m11", "type": "mcq", "group": "w2", "prompt": "Why preserve a well-learned control mapping?", "options": ["Automatic processes are difficult to unlearn", "Automatic processes never cause errors", "Learning removes individual differences", "Controlled processes cannot adapt"], "correct": 0, "explanation": "Changing a habitual mapping can create errors and extra effort.", "source": "Week 2 · PDF pp. 43–45", "topic": "Cognition", "origin": "lecture", "level": "concept"}, {"id": "w2-m12", "type": "mcq", "group": "w2", "prompt": "Which task most clearly requires controlled processing?", "options": ["Working out an unfamiliar calculation", "Typing a familiar word as a skilled typist", "Executing a well-practised shortcut", "Performing a habitual motor sequence"], "correct": 0, "explanation": "Controlled processes require conscious attention.", "source": "Week 2 · PDF p. 44", "topic": "Cognition", "origin": "lecture", "level": "concept"}, {"id": "w2-m13", "type": "mcq", "group": "w2", "prompt": "Labels close to their fields use which Gestalt principle?", "options": ["Proximity", "Closure", "Continuity", "Opponent processing"], "correct": 0, "explanation": "Nearby items tend to be perceived as related.", "source": "Week 2 · PDF pp. 58–60", "topic": "Gestalt", "origin": "lecture", "level": "application"}, {"id": "w2-m14", "type": "mcq", "group": "w2", "prompt": "Controls with the same shape and styling tend to form a group through what?", "options": ["Similarity", "Closure", "Homing", "Recall"], "correct": 0, "explanation": "Similarity groups objects through shared visual features.", "source": "Week 2 · PDF p. 61", "topic": "Gestalt", "origin": "lecture", "level": "application"}, {"id": "w2-m15", "type": "mcq", "group": "w2", "prompt": "Recognizing an incomplete outline as a whole shape illustrates what?", "options": ["Closure", "Divided attention", "Negative transfer", "Dynamic range"], "correct": 0, "explanation": "Closure supports perceiving incomplete figures as wholes.", "source": "Week 2 · PDF p. 64", "topic": "Gestalt", "origin": "lecture", "level": "application"}, {"id": "w2-m16", "type": "mcq", "group": "w2", "prompt": "Seeing a route as continuous despite an overlapping object illustrates what?", "options": ["Continuity", "Prestige bias", "Encoding failure", "Chunking by meaning"], "correct": 0, "explanation": "Continuity favours smooth, continuous objects or paths.", "source": "Week 2 · PDF pp. 62–63", "topic": "Gestalt", "origin": "lecture", "level": "application"}, {"id": "w2-m17", "type": "mcq", "group": "w2", "prompt": "Why can a structured table be easier to scan than dense prose with the same information?", "options": ["Grouping and alignment support search", "The table must contain less information", "It increases working-memory capacity", "It removes the need for attention"], "correct": 0, "explanation": "Information organization affects search even at similar density.", "source": "Week 2 · PDF pp. 73–79, 124–126", "topic": "Visual hierarchy", "origin": "lecture", "level": "application"}, {"id": "w2-m18", "type": "mcq", "group": "w2", "prompt": "Which photoreceptors support highly sensitive low-light vision?", "options": ["Rods", "Cones only", "The pupil", "The cornea"], "correct": 0, "explanation": "Rods support scotopic vision with low spatial detail.", "source": "Week 2 · PDF pp. 90, 97", "topic": "Vision", "origin": "lecture", "level": "concept"}, {"id": "w2-m19", "type": "mcq", "group": "w2", "prompt": "Why should error meaning also be communicated with text or symbols?", "options": ["Colour discrimination varies across users and conditions", "Colour never communicates anything useful", "Text eliminates all visual impairments", "Every display renders colour identically"], "correct": 0, "explanation": "Redundant cues reduce reliance on colour alone.", "source": "Week 2 · PDF pp. 110–114", "topic": "Colour", "origin": "lecture", "level": "concept"}, {"id": "w2-m20", "type": "mcq", "group": "w2", "prompt": "Which situation best illustrates inattentional blindness?", "options": ["Missing an unexpected object while concentrating elsewhere", "Forgetting a password after several months", "Being unable to hear a high-frequency sound", "Correctly recognizing a familiar icon"], "correct": 0, "explanation": "Focused attention can cause visible events to be missed.", "source": "Week 2 · PDF p. 127", "topic": "Attention", "origin": "lecture", "level": "application"}, {"id": "w2-m21", "type": "mcq", "group": "w2", "prompt": "Failing to notice that a display changed while looking away is what?", "options": ["Change blindness", "Annotation", "Near transfer", "Deliberate practice"], "correct": 0, "explanation": "A change can go unnoticed even when the new state is visible.", "source": "Week 1 · PDF p. 46; Week 2 p. 127", "topic": "Attention", "origin": "lecture", "level": "application"}, {"id": "w2-m22", "type": "mcq", "group": "w2", "prompt": "The Stroop effect illustrates what?", "options": ["Automatic reading interfering with controlled colour naming", "A joystick returning to centre", "The inability to recognize incomplete shapes", "A survey’s low response rate"], "correct": 0, "explanation": "Automatic processes can compete with a task needing conscious attention.", "source": "Week 2 · PDF p. 129", "topic": "Attention", "origin": "lecture", "level": "concept"}, {"id": "w2-m23", "type": "mcq", "group": "w2", "prompt": "Why are visible menu choices often easier than remembered commands?", "options": ["They support recognition rather than recall", "They increase long-term memory storage physically", "They remove every choice from the task", "They depend only on auditory memory"], "correct": 0, "explanation": "Recognizing presented information generally places less demand on memory.", "source": "Week 2 · PDF pp. 139, 145–146", "topic": "Memory", "origin": "lecture", "level": "concept"}, {"id": "w2-m24", "type": "mcq", "group": "w2", "prompt": "Grouping a phone number into familiar units primarily supports what?", "options": ["Chunking", "Colour opponency", "A physical neutral position", "Far transfer by default"], "correct": 0, "explanation": "Meaningful groups reduce the number of separate units to process.", "source": "Week 2 · PDF pp. 142–144", "topic": "Memory", "origin": "lecture", "level": "application"}, {"id": "w2-m25", "type": "mcq", "group": "w2", "prompt": "Why can tiny fonts and jargon reduce comprehension?", "options": ["They can force more effortful reading and burden working memory", "They reliably speed up automatic reading", "They improve recognition through unfamiliarity", "They prevent users from needing context"], "correct": 0, "explanation": "Poor text presentation increases reading effort.", "source": "Week 2 · PDF pp. 149–160", "topic": "Reading", "origin": "lecture", "level": "concept"}, {"id": "w3-m01", "type": "mcq", "group": "w3", "prompt": "An input reports how far it moved since the last reading. How is it classified?", "options": ["Relative", "Absolute", "Binary by definition", "Direct by definition"], "correct": 0, "explanation": "Relative input reports a change rather than an absolute position.", "source": "Week 3 · PDF p. 4", "topic": "Device taxonomy", "origin": "lecture", "level": "application"}, {"id": "w3-m02", "type": "mcq", "group": "w3", "prompt": "A touchscreen reports the touched location. Which classification is most appropriate?", "options": ["Absolute and direct", "Relative and indirect", "Binary and indirect", "Relative and binary"], "correct": 0, "explanation": "A touchscreen normally supplies coordinates on the display itself.", "source": "Week 3 · PDF pp. 4–5", "topic": "Device taxonomy", "origin": "lecture", "level": "application"}, {"id": "w3-m03", "type": "mcq", "group": "w3", "prompt": "Moving a mouse on a desk to move a screen pointer is what kind of input?", "options": ["Indirect", "Direct", "Always one-dimensional", "Always absolute"], "correct": 0, "explanation": "An indirect device maps action elsewhere onto screen activity.", "source": "Week 3 · PDF p. 5", "topic": "Device taxonomy", "origin": "lecture", "level": "application"}, {"id": "w3-m04", "type": "mcq", "group": "w3", "prompt": "What distinguishes analog from binary input in this lecture?", "options": ["A range of values rather than two states", "A device using electricity rather than springs", "An input that must use an analog cable", "A device that always returns to centre"], "correct": 0, "explanation": "Analog here describes values, even when digitally encoded.", "source": "Week 3 · PDF p. 6", "topic": "Device taxonomy", "origin": "lecture", "level": "concept"}, {"id": "w3-m05", "type": "mcq", "group": "w3", "prompt": "Which control normally has a spring-return neutral position?", "options": ["A joystick", "A mouse body", "A touchscreen’s stored coordinates", "A trackball’s physical location"], "correct": 0, "explanation": "Joysticks commonly return to the centre when released.", "source": "Week 3 · PDF pp. 7, 15", "topic": "Device taxonomy", "origin": "lecture", "level": "concept"}, {"id": "w3-m06", "type": "mcq", "group": "w3", "prompt": "What does the dimensionality of a device describe?", "options": ["The independent values it transmits", "Its physical screen diagonal", "The number of installed apps", "Its battery capacity"], "correct": 0, "explanation": "A 2D position input provides two components such as X and Y.", "source": "Week 3 · PDF p. 3", "topic": "Device taxonomy", "origin": "lecture", "level": "concept"}, {"id": "w3-m07", "type": "mcq", "group": "w3", "prompt": "Which is a typical one-dimensional relative input?", "options": ["An unlimited-turn mouse wheel", "A touchscreen’s X and Y position", "A GPS position including altitude", "A six-degree-of-freedom tracker"], "correct": 0, "explanation": "The wheel reports movement along one input dimension.", "source": "Week 3 · PDF p. 10", "topic": "Devices", "origin": "lecture", "level": "application"}, {"id": "w3-m08", "type": "mcq", "group": "w3", "prompt": "What is mouse clutching?", "options": ["Repositioning the mouse to continue pointer travel", "Holding a key to repeat text", "Tilting a joystick to set speed", "Locking a touchscreen orientation"], "correct": 0, "explanation": "Clutching overcomes limits of physical travel on the surface.", "source": "Week 3 · PDF p. 11", "topic": "Devices", "origin": "lecture", "level": "concept"}, {"id": "w3-m09", "type": "mcq", "group": "w3", "prompt": "Why may a mouse be poor for a steering task requiring a resting centre?", "options": ["It lacks an automatic neutral return", "It cannot report X and Y", "It only has binary movement", "It cannot support precise pointing"], "correct": 0, "explanation": "No automatic centre can make steering state harder to manage.", "source": "Week 3 · PDF p. 12", "topic": "Devices", "origin": "lecture", "level": "application"}, {"id": "w3-m10", "type": "mcq", "group": "w3", "prompt": "Why are small touch targets difficult?", "options": ["Finger imprecision and occlusion", "Touch input cannot report coordinates", "High pixel resolution guarantees large controls", "All users have the same finger size"], "correct": 0, "explanation": "A finger can cover and inaccurately select a small target.", "source": "Week 3 · PDF pp. 13, 48, 52", "topic": "Mobile input", "origin": "lecture", "level": "application"}, {"id": "w3-m11", "type": "mcq", "group": "w3", "prompt": "A touchpad senses finger coordinates but moves a cursor by changes in those coordinates. What is true?", "options": ["Absolute sensing can support relative pointer behaviour", "Its hardware must be binary", "Its cursor is necessarily direct input", "The two descriptions are impossible together"], "correct": 0, "explanation": "Sensor readings and software interpretation are different levels.", "source": "Week 3 · PDF pp. 4, 13", "topic": "Device taxonomy", "origin": "lecture", "level": "application"}, {"id": "w3-m12", "type": "mcq", "group": "w3", "prompt": "Why is a joystick useful for continuous steering?", "options": ["Tilt can represent direction and movement rate", "It has unlimited physical travel", "It always outperforms a mouse for precise pointing", "It reports geographic coordinates"], "correct": 0, "explanation": "Limited tilt can control ongoing movement by rate.", "source": "Week 3 · PDF pp. 15–16", "topic": "Devices", "origin": "lecture", "level": "application"}, {"id": "w3-m13", "type": "mcq", "group": "w3", "prompt": "How can a D-pad provide diagonal directions?", "options": ["By activating two directional switches together", "By measuring latitude and longitude", "By continuously estimating rotation", "By physically rotating the entire display"], "correct": 0, "explanation": "Combinations of the four switches support eight directions.", "source": "Week 3 · PDF p. 17", "topic": "Devices", "origin": "lecture", "level": "application"}, {"id": "w3-m14", "type": "mcq", "group": "w3", "prompt": "What does an accelerometer measure?", "options": ["Acceleration", "Angular velocity", "Magnetic field only", "Latitude and longitude"], "correct": 0, "explanation": "The accelerometer measures acceleration, including gravity-related readings.", "source": "Week 3 · PDF p. 18", "topic": "Sensors", "origin": "lecture", "level": "concept"}, {"id": "w3-m15", "type": "mcq", "group": "w3", "prompt": "What does a gyroscope measure?", "options": ["Angular velocity", "Linear position", "Ambient illumination", "Food energy"], "correct": 0, "explanation": "Angular velocity is the rate of rotation.", "source": "Week 3 · PDF p. 19", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-m16", "type": "mcq", "group": "w3", "prompt": "What can be estimated by integrating angular velocity?", "options": ["Orientation change", "Sound pressure", "Screen luminance", "A food’s nutrient composition"], "correct": 0, "explanation": "Integrating rotation rate estimates a change in orientation.", "source": "Week 3 · PDF p. 19", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-m17", "type": "mcq", "group": "w3", "prompt": "Why does estimating position from acceleration become inaccurate?", "options": ["Noise accumulates through integration", "Acceleration is identical to absolute position", "Integration removes every measurement error", "A gyroscope supplies error-free geographic coordinates"], "correct": 0, "explanation": "Double integration can accumulate error and drift.", "source": "Week 3 · PDF p. 18", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-m18", "type": "mcq", "group": "w3", "prompt": "Which sensor supports geographic location-based results?", "options": ["GPS", "A proximity sensor", "A gyroscope alone", "A light sensor"], "correct": 0, "explanation": "GPS provides geographic position.", "source": "Week 3 · PDF p. 20", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-m19", "type": "mcq", "group": "w3", "prompt": "Which sensor can contribute to compass heading?", "options": ["Magnetometer", "Microphone only", "Proximity sensor only", "Screen touch pressure only"], "correct": 0, "explanation": "A magnetometer measures magnetic-field components.", "source": "Week 3 · PDF p. 21", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-m20", "type": "mcq", "group": "w3", "prompt": "What is a derived sensor reading?", "options": ["Information calculated by combining or processing sensor data", "A sensor with no measured input", "An exclusively mechanical switch", "A guarantee of perfect position"], "correct": 0, "explanation": "Orientation and linear acceleration can be derived from sensor readings.", "source": "Week 3 · PDF p. 23", "topic": "Sensors", "origin": "lecture", "level": "concept"}, {"id": "w3-m21", "type": "mcq", "group": "w3", "prompt": "Six degrees of freedom includes what?", "options": ["Three translations and three rotations", "Six independent colour channels", "Six geographic latitudes", "Six binary keyboard keys"], "correct": 0, "explanation": "3D tracking can represent position and orientation.", "source": "Week 3 · PDF p. 24", "topic": "Tracking", "origin": "lecture", "level": "concept"}, {"id": "w3-m22", "type": "mcq", "group": "w3", "prompt": "What distinguishes haptic feedback?", "options": ["It provides tactile or force information", "It exclusively changes font size", "It always uses spoken instructions", "It is geographic positioning"], "correct": 0, "explanation": "Haptic devices create physical feedback.", "source": "Week 3 · PDF p. 25", "topic": "Tracking", "origin": "lecture", "level": "concept"}, {"id": "w3-m23", "type": "mcq", "group": "w3", "prompt": "Why should a VR interface reconsider corner-based status displays?", "options": ["They can be uncomfortable to monitor and cause eye strain", "VR makes all text automatically larger", "A desktop layout is always optimal in VR", "Head movement eliminates attention limits"], "correct": 0, "explanation": "VR changes viewing, navigation, safety, and feedback requirements.", "source": "Week 3 · PDF pp. 30–35", "topic": "VR", "origin": "lecture", "level": "application"}, {"id": "w3-m24", "type": "mcq", "group": "w3", "prompt": "Why use events rather than repeatedly polling on mobile?", "options": ["To reduce unnecessary activity and wake-ups", "To guarantee network connectivity", "To remove the need for a processor", "To disable all notifications"], "correct": 0, "explanation": "Event-driven updates can help conserve limited energy.", "source": "Week 3 · PDF pp. 46–47", "topic": "Mobile constraints", "origin": "lecture", "level": "application"}, {"id": "w3-m25", "type": "mcq", "group": "w3", "prompt": "What makes mobile design more than shrinking a desktop layout?", "options": ["Touch, context, attention, resources and usage patterns differ", "Only the number of pixels differs", "Mobile users never multitask", "Responsive layout guarantees every task is easy"], "correct": 0, "explanation": "Mobile design must support the actual platform and use context.", "source": "Week 3 · PDF pp. 41–65", "topic": "Mobile constraints", "origin": "lecture", "level": "application"}, {"id": "w4-m01", "type": "mcq", "group": "w4", "prompt": "What is the starting question of task-centred design?", "options": ["Who will use the system to do exactly what?", "Which framework has the most features?", "Which colour is fashionable?", "How can users be trained to accept the design?"], "correct": 0, "explanation": "Task-centred design begins with users and concrete tasks.", "source": "Week 4 · PDF p. 6", "topic": "Requirements", "origin": "lecture", "level": "concept"}, {"id": "w4-m02", "type": "mcq", "group": "w4", "prompt": "Which is a functional requirement?", "options": ["Allow users to cancel a booking", "Respond within one second", "Keep information no more than five minutes old", "Remain readable in the intended lighting"], "correct": 0, "explanation": "A functional requirement describes what the system does.", "source": "Week 4 · PDF p. 17", "topic": "Requirements", "origin": "lecture", "level": "application"}, {"id": "w4-m03", "type": "mcq", "group": "w4", "prompt": "Which is a non-functional requirement?", "options": ["Search results appear within the selected time target", "Users can search for meals", "Users can delete entries", "Users can create a shopping list"], "correct": 0, "explanation": "A non-functional requirement sets a quality or constraint.", "source": "Week 4 · PDF p. 17", "topic": "Requirements", "origin": "lecture", "level": "application"}, {"id": "w4-m04", "type": "mcq", "group": "w4", "prompt": "Which statement about users is most accurate?", "options": ["A frequent user can remain inexperienced in many features", "Every frequent user becomes an expert", "Every expert uses the system daily", "Occasional users never need guidance"], "correct": 0, "explanation": "Expertise and frequency of use are distinct.", "source": "Week 4 · PDF pp. 16, 27–28", "topic": "Users", "origin": "lecture", "level": "application"}, {"id": "w4-m05", "type": "mcq", "group": "w4", "prompt": "A person affected by a system but not operating it is what?", "options": ["A stakeholder", "Necessarily its primary user", "Necessarily the interface designer", "Not relevant to requirements"], "correct": 0, "explanation": "Stakeholders influence or are affected by the system.", "source": "Week 4 · PDF p. 21", "topic": "Users", "origin": "lecture", "level": "application"}, {"id": "w4-m06", "type": "mcq", "group": "w4", "prompt": "Noise, vibration and lighting belong to which context?", "options": ["Physical", "Organizational hierarchy", "A use-case postcondition", "A persona name"], "correct": 0, "explanation": "Physical context affects how interaction works.", "source": "Week 4 · PDF p. 18", "topic": "Context", "origin": "lecture", "level": "application"}, {"id": "w4-m07", "type": "mcq", "group": "w4", "prompt": "Why ask why a user requests a feature?", "options": ["To identify the underlying goal", "To prove users never know their needs", "To reject every request", "To choose colours before understanding tasks"], "correct": 0, "explanation": "A requested feature may be one possible means to a goal.", "source": "Week 4 · PDF pp. 23–26", "topic": "Requirements", "origin": "lecture", "level": "concept"}, {"id": "w4-m08", "type": "mcq", "group": "w4", "prompt": "Which interview combines prepared questions with flexible follow-up?", "options": ["Semi-structured", "Structured only", "A closed survey only", "A state-machine interview"], "correct": 0, "explanation": "Semi-structured interviewing covers a guide while exploring new issues.", "source": "Week 4 · PDF p. 31", "topic": "Interviews", "origin": "lecture", "level": "concept"}, {"id": "w4-m09", "type": "mcq", "group": "w4", "prompt": "What is a limitation of interviews?", "options": ["Reported accounts can be subjective and affected by the interviewer", "They can never explore reasons", "They require no analysis", "They directly capture all real behaviour"], "correct": 0, "explanation": "Interviews provide reported information and can introduce bias.", "source": "Week 4 · PDF pp. 30–33", "topic": "Interviews", "origin": "lecture", "level": "concept"}, {"id": "w4-m10", "type": "mcq", "group": "w4", "prompt": "Which question is least leading?", "options": ["Tell me how you completed your last booking.", "Wasn’t our booking screen convenient?", "You liked the easy controls, right?", "Would you agree our excellent design saved time?"], "correct": 0, "explanation": "A concrete neutral question avoids suggesting a desired answer.", "source": "Week 4 · PDF pp. 33, 42", "topic": "Bias", "origin": "lecture", "level": "application"}, {"id": "w4-m11", "type": "mcq", "group": "w4", "prompt": "What can distort a focus group’s apparent agreement?", "options": ["Dominant participants and reluctance to disagree", "Its use of a moderator by itself", "Every person being asked the same task", "Participants seeing the same mock-up"], "correct": 0, "explanation": "Social dynamics can suppress individual opinions.", "source": "Week 4 · PDF pp. 35–36", "topic": "Focus groups", "origin": "lecture", "level": "concept"}, {"id": "w4-m12", "type": "mcq", "group": "w4", "prompt": "Which question is primarily attitudinal?", "options": ["How useful was the task summary?", "How many appointments did you book yesterday?", "Which browser version did you use?", "How long have you used the system?"], "correct": 0, "explanation": "Attitudinal questions examine judgments and preferences.", "source": "Week 4 · PDF p. 39", "topic": "Questionnaires", "origin": "lecture", "level": "application"}, {"id": "w4-m13", "type": "mcq", "group": "w4", "prompt": "How does ranking differ from rating?", "options": ["Ranking orders items; rating judges items on a scale", "Ranking always explains reasons", "Rating forces every item into a unique order", "The two methods are identical"], "correct": 0, "explanation": "Rank order does not directly show the strength of each judgment.", "source": "Week 4 · PDF p. 41", "topic": "Questionnaires", "origin": "lecture", "level": "concept"}, {"id": "w4-m14", "type": "mcq", "group": "w4", "prompt": "A respondent exaggerates expertise to look impressive. Which bias is illustrated?", "options": ["Prestige bias", "Change blindness", "Control-display mapping", "A relative input effect"], "correct": 0, "explanation": "Prestige bias changes answers to improve perceived status.", "source": "Week 4 · PDF p. 42", "topic": "Bias", "origin": "lecture", "level": "application"}, {"id": "w4-m15", "type": "mcq", "group": "w4", "prompt": "What is funnelling in question design?", "options": ["Moving from broad questions to specific ones", "Starting by praising the feature", "Repeating the same question until agreement", "Combining unrelated topics in one question"], "correct": 0, "explanation": "Funnelling establishes context without prematurely directing answers.", "source": "Week 4 · PDF p. 43", "topic": "Questionnaires", "origin": "lecture", "level": "concept"}, {"id": "w4-m16", "type": "mcq", "group": "w4", "prompt": "What is simple observation’s main limitation?", "options": ["It may not reveal users’ reasoning", "It cannot reveal actions", "It always provides a full mental model", "It removes observer influence"], "correct": 0, "explanation": "Watching reveals behaviour, but may not explain why.", "source": "Week 4 · PDF p. 48", "topic": "Observation", "origin": "lecture", "level": "concept"}, {"id": "w4-m17", "type": "mcq", "group": "w4", "prompt": "What does think-aloud add to observation?", "options": ["Users verbalize goals, beliefs and reasons", "Users silently rank colours", "An evaluator performs every task", "A model automatically assigns grades"], "correct": 0, "explanation": "Think-aloud offers reasoning but can also alter performance.", "source": "Week 4 · PDF p. 49", "topic": "Observation", "origin": "lecture", "level": "concept"}, {"id": "w4-m18", "type": "mcq", "group": "w4", "prompt": "Which best describes co-discovery in the lecture?", "options": ["A novice uses the interface while conversing with a coach", "An evaluator secretly changes responses", "A group silently completes a questionnaire", "An expert demonstrates while the novice watches silently"], "correct": 0, "explanation": "Conversation can reveal reasoning more naturally than continuous narration.", "source": "Week 4 · PDF p. 50", "topic": "Observation", "origin": "lecture", "level": "concept"}, {"id": "w4-m19", "type": "mcq", "group": "w4", "prompt": "Context, partnership, interpretation and focus are principles of what?", "options": ["Contextual inquiry", "A Likert scale", "HTA decomposition", "Colour naming"], "correct": 0, "explanation": "Contextual inquiry studies actual activity through focused collaboration.", "source": "Week 4 · PDF pp. 55–56", "topic": "Contextual inquiry", "origin": "lecture", "level": "concept"}, {"id": "w4-m20", "type": "mcq", "group": "w4", "prompt": "What does triangulation involve?", "options": ["Combining techniques or sources to examine a question", "Using exactly three participants in every study", "Repeating one leading question", "Treating one survey as complete proof"], "correct": 0, "explanation": "Multiple perspectives can corroborate or challenge findings.", "source": "Week 4 · PDF p. 61", "topic": "Research design", "origin": "lecture", "level": "concept"}, {"id": "w4-m21", "type": "mcq", "group": "w4", "prompt": "What makes a persona appropriate for requirements work?", "options": ["It synthesizes meaningful characteristics from real user data", "It matches the designer’s ideal user", "It uses a realistic photo without evidence", "It replaces all user research"], "correct": 0, "explanation": "Personas should represent evidence rather than convenient inventions.", "source": "Week 4 · PDF p. 66", "topic": "Personas", "origin": "lecture", "level": "application"}, {"id": "w4-m22", "type": "mcq", "group": "w4", "prompt": "Which description matches a scenario in this lecture?", "options": ["A concrete narrative following one path in context", "A branching specification of every possible screen", "A database schema", "A list of colour values"], "correct": 0, "explanation": "Scenarios tell a particular story without conditional branches.", "source": "Week 4 · PDF pp. 68–69", "topic": "Models", "origin": "lecture", "level": "application"}, {"id": "w4-m23", "type": "mcq", "group": "w4", "prompt": "What do essential use cases emphasize?", "options": ["User intentions and system responsibilities", "Exact icon locations and click coordinates", "Only exception codes", "Hardware benchmark results"], "correct": 0, "explanation": "They abstract away from specific interface details.", "source": "Week 4 · PDF p. 75", "topic": "Models", "origin": "lecture", "level": "concept"}, {"id": "w4-m24", "type": "mcq", "group": "w4", "prompt": "What does an HTA plan specify?", "options": ["Order, conditions and repetition of subtasks", "Only font choices", "Only a fictional user’s age", "Only the database transaction count"], "correct": 0, "explanation": "A hierarchy needs a plan to describe how tasks are performed.", "source": "Week 4 · PDF pp. 77–79", "topic": "HTA", "origin": "lecture", "level": "concept"}, {"id": "w4-m25", "type": "mcq", "group": "w4", "prompt": "What does a state diagram primarily represent?", "options": ["System states and transitions", "The target users’ biographies", "A list of functional goals alone", "The ranking of survey responses"], "correct": 0, "explanation": "State diagrams expose conditions and transitions such as loading and errors.", "source": "Week 4 · PDF p. 82", "topic": "State diagrams", "origin": "lecture", "level": "concept"}, {"id": "project-m01", "type": "mcq", "group": "project", "prompt": "For a four-member group, how many complex tasks should the interface support under the topic rule?", "options": ["At least four", "Exactly one", "Two regardless of membership", "Only as many as fit one screen"], "correct": 0, "explanation": "The supplied topic rule ties complex-task count to group size.", "source": "Project topic brief", "topic": "Assignment scope", "origin": "optional", "level": "concept"}, {"id": "project-m02", "type": "mcq", "group": "project", "prompt": "How many people should submit the group declaration?", "options": ["One member for the whole group", "Every member separately", "Only the instructor", "No one if a topic was discussed"], "correct": 0, "explanation": "The supplied instructions require one group submission.", "source": "Group declaration brief", "topic": "Declaration", "origin": "optional", "level": "concept"}, {"id": "project-m03", "type": "mcq", "group": "project", "prompt": "What must each member line in the declaration contain?", "options": ["Official name, email, repeated group/topic name", "Nickname and favourite app", "Only the team name", "Only the topic description"], "correct": 0, "explanation": "The required format is comma-separated name, email and group name.", "source": "Group declaration brief", "topic": "Declaration", "origin": "optional", "level": "concept"}, {"id": "project-m04", "type": "mcq", "group": "project", "prompt": "What is the stated questionnaire maximum?", "options": ["Seven closed-ended and two open-ended questions", "Ten open-ended questions", "Seven questions of any kind without restrictions", "Two closed-ended and seven open-ended questions"], "correct": 0, "explanation": "Use Google Forms and include its link in the submission.", "source": "Walkthrough brief · Questionnaire", "topic": "Questionnaire", "origin": "optional", "level": "concept"}, {"id": "project-m05", "type": "mcq", "group": "project", "prompt": "Which walkthrough component has the greatest marking weight?", "options": ["Conceptual model and low-fidelity prototype", "Problem overview", "Requirements and tasks", "Questionnaire alone"], "correct": 0, "explanation": "The supplied weights are 40%, 15%, 20%, and 25% respectively.", "source": "Walkthrough brief · Marking scheme", "topic": "Assignment scope", "origin": "optional", "level": "concept"}, {"id": "project-m06", "type": "mcq", "group": "project", "prompt": "Which statement is an appropriately testable design rationale?", "options": ["We expect fewer steps to help; we will test task completion.", "The design is obviously perfect.", "AI makes usability evaluation unnecessary.", "Everyone will find the interface intuitive."], "correct": 0, "explanation": "The brief asks for observable evidence and explicit hypotheses.", "source": "Walkthrough brief · Prototype", "topic": "Design evidence", "origin": "optional", "level": "concept"}, {"id": "project-m07", "type": "mcq", "group": "project", "prompt": "For the nutrition concept, what does a daily food log establish by itself?", "options": ["Logged estimated intake, not actual energy balance", "A guaranteed physiological calorie deficit", "Clinically optimal sleep timing", "The user’s exact energy expenditure"], "correct": 0, "explanation": "Your idea needs clear distinctions between logs, targets and untested claims.", "source": "Idea screenshot + proposed project outline", "topic": "Nutrition concept", "origin": "optional", "level": "concept"}, {"id": "project-m08", "type": "mcq", "group": "project", "prompt": "Which flow is more substantial for the prototype?", "options": ["Choose a meal, inspect a suggestion, swap an ingredient, then save a shopping list", "Show one static food icon", "Open a decorative splash screen", "Rename the app"], "correct": 0, "explanation": "A complex task connects decisions, screens, results and recovery.", "source": "Idea screenshot + project task rule", "topic": "Nutrition concept", "origin": "optional", "level": "concept"}, {"id": "extra-m01", "type": "mcq", "group": "extra", "prompt": "In the other professor’s photo, which HTML input type selects a date?", "options": ["input type=\"date\"", "input type=\"calendar\"", "input type=\"schedule\"", "input type=\"appointment\""], "correct": 0, "explanation": "The photo’s date-input question uses the standard date type.", "source": "Other professor · IMG_4847.JPG", "topic": "HTML / CSS", "origin": "optional", "level": "concept"}, {"id": "extra-m02", "type": "mcq", "group": "extra", "prompt": "In the supplied sample, what does .col-md-6 represent?", "options": ["Half-width at medium screens and up", "Six rows on medium screens", "A fixed 600-pixel width", "A non-responsive column"], "correct": 0, "explanation": "Six of twelve grid columns occupy half the row at the applicable breakpoint.", "source": "Other professor · IMG_4847.JPG", "topic": "HTML / CSS", "origin": "optional", "level": "concept"}, {"id": "extra-m03", "type": "mcq", "group": "extra", "prompt": "Which selector targets paragraph descendants of a div?", "options": ["div p", "div.p", "p div", "div > p2"], "correct": 0, "explanation": "The space is the descendant combinator.", "source": "Other professor · IMG_4847.JPG", "topic": "HTML / CSS", "origin": "optional", "level": "concept"}, {"id": "extra-m04", "type": "mcq", "group": "extra", "prompt": "Which sample item is quantitative usability data?", "options": ["Task-completion time", "A frustration comment", "An open interview response", "A suggestion in the user’s words"], "correct": 0, "explanation": "Time is a numerical measure; comments provide qualitative information.", "source": "Other professor · IMG_4847.JPG", "topic": "Evaluation extras", "origin": "optional", "level": "concept"}, {"id": "extra-m05", "type": "mcq", "group": "extra", "prompt": "Which chart is best for comparing categories in the sample?", "options": ["Bar chart", "Line chart for a time trend", "Scatterplot for two-variable relationships", "Box plot for distribution summaries"], "correct": 0, "explanation": "Bars support comparison across categories.", "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras", "origin": "optional", "level": "concept"}, {"id": "extra-m06", "type": "mcq", "group": "extra", "prompt": "A single 1–5 Likert item is classified as what in the supplied sample?", "options": ["Ordinal", "Ratio", "Nominal", "Automatically interval"], "correct": 0, "explanation": "The response categories are ordered; equal gaps are not guaranteed.", "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras", "origin": "optional", "level": "concept"}, {"id": "extra-m07", "type": "mcq", "group": "extra", "prompt": "Which method in the sample is qualitative analysis?", "options": ["Thematic analysis", "Task-completion time", "Error rate", "Completion percentage"], "correct": 0, "explanation": "Thematic analysis identifies patterns in qualitative data.", "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras", "origin": "optional", "level": "concept"}, {"id": "extra-m08", "type": "mcq", "group": "extra", "prompt": "Which best matches user control and freedom in the sample?", "options": ["Allow users to leave and reverse actions where appropriate", "Prohibit undo", "Make every button identical", "Prevent all choices"], "correct": 0, "explanation": "The supplied question emphasizes exits and reversible actions.", "source": "Other professor · IMG_4847.JPG", "topic": "Evaluation extras", "origin": "optional", "level": "concept"}, {"id": "context-m01", "type": "mcq", "group": "context", "prompt": "What is the central idea of constructivist perception in the excluded slides?", "options": ["Perception uses sensory information and prior knowledge", "Vision is an exact camera copy", "Prior experience never affects seeing", "Perception depends only on keyboard input"], "correct": 0, "explanation": "These Week 2 slides are explicitly marked Not on test.", "source": "Week 2 · PDF pp. 66–70 · Not on test", "topic": "Constructivism", "origin": "optional", "level": "concept"}, {"id": "context-m02", "type": "mcq", "group": "context", "prompt": "Gregory’s hypothesis theory treats perception as what?", "options": ["Building interpretations of the world from received stimuli", "Measuring only processor speed", "Ignoring familiar objects", "An error-free reproduction of light"], "correct": 0, "explanation": "This theory is background material in slides marked Not on test.", "source": "Week 2 · PDF p. 69 · Not on test", "topic": "Constructivism", "origin": "optional", "level": "concept"}, {"id": "context-m03", "type": "mcq", "group": "context", "prompt": "Interaural level differences refer to what?", "options": ["Differences in sound level at the two ears", "Differences in colour between two eyes", "Only the text size on a screen", "The number of sensory stores"], "correct": 0, "explanation": "The detailed sound-localization slide is marked Not on test.", "source": "Week 2 · PDF p. 86 · Not on test", "topic": "Sound localization", "origin": "optional", "level": "concept"}, {"id": "context-m04", "type": "mcq", "group": "context", "prompt": "Interaural time differences involve what?", "options": ["Differences in when sound reaches each ear", "Changes in screen refresh rate", "The time taken to read a command", "The time between keyboard events"], "correct": 0, "explanation": "This is optional background from the sound-localization slide.", "source": "Week 2 · PDF p. 86 · Not on test", "topic": "Sound localization", "origin": "optional", "level": "concept"}, {"id": "w1-s01", "type": "short", "group": "w1", "prompt": "Distinguish utility from usability.", "answer": ["Utility means the system provides the functions users need.", "Usability means users can operate those functions successfully and easily."], "source": "Week 1 · PDF pp. 73, 78", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-s02", "type": "short", "group": "w1", "prompt": "Distinguish effectiveness from efficiency.", "answer": ["Effectiveness is completing the intended goal accurately.", "Efficiency is the time and effort required to complete it."], "source": "Week 1 · PDF p. 73", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-s03", "type": "short", "group": "w1", "prompt": "Distinguish learnability from memorability.", "answer": ["Learnability concerns learning to use a system initially.", "Memorability concerns remembering how to use it after time away."], "source": "Week 1 · PDF p. 73", "topic": "Usability goals", "origin": "lecture", "level": "application"}, {"id": "w1-s04", "type": "short", "group": "w1", "prompt": "Explain why design should account for human error.", "answer": ["Distraction, fatigue and memory limits are predictable human characteristics.", "Design should reduce likely errors and support recovery instead of simply blaming users."], "source": "Week 1 · PDF pp. 42–43, 59", "topic": "Human error", "origin": "lecture", "level": "application"}, {"id": "w1-s05", "type": "short", "group": "w1", "prompt": "Define mapping and give one example.", "answer": ["Mapping is the relationship between controls and their effects.", "Stove controls matching burner positions make the relationship easier to understand."], "source": "Week 1 · PDF p. 87", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-s06", "type": "short", "group": "w1", "prompt": "Distinguish visibility from feedback.", "answer": ["Visibility makes available actions or relevant states apparent.", "Feedback communicates what happened after an action."], "source": "Week 1 · PDF pp. 88–91", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-s07", "type": "short", "group": "w1", "prompt": "Define a perceived affordance in a graphical interface.", "answer": ["Appearance and learned conventions suggest how an interface element can be used.", "A button’s familiar styling suggests that it can be clicked."], "source": "Week 1 · PDF pp. 80–81", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-s08", "type": "short", "group": "w1", "prompt": "A disabled time selector gives no reason. Identify a problem and a fix.", "answer": ["The constraint is unexplained, so users cannot determine what to do next.", "Show “Choose a doctor and date first” beside the selector."], "source": "Week 1 · PDF pp. 91, 96", "topic": "Application", "origin": "lecture", "level": "application"}, {"id": "w1-s09", "type": "short", "group": "w1", "prompt": "Explain positive and negative transfer.", "answer": ["Positive transfer occurs when prior experience helps a new task.", "Negative transfer occurs when prior experience interferes with it."], "source": "Week 1 · PDF pp. 50–51, 92–93", "topic": "Transfer", "origin": "lecture", "level": "application"}, {"id": "w1-s10", "type": "short", "group": "w1", "prompt": "Why does consistency matter?", "answer": ["Stable controls and terminology reduce learning demands and support familiar habits.", "Similar operations should behave similarly while different functions remain distinguishable."], "source": "Week 1 · PDF pp. 97–100", "topic": "Design principles", "origin": "lecture", "level": "application"}, {"id": "w1-s11", "type": "short", "group": "w1", "prompt": "Distinguish usability goals from UX goals.", "answer": ["Usability goals concern successful, efficient, safe and learnable interaction.", "UX goals concern experiences such as satisfaction, engagement and enjoyment."], "source": "Week 1 · PDF pp. 73, 76", "topic": "User experience", "origin": "lecture", "level": "application"}, {"id": "w1-s12", "type": "short", "group": "w1", "prompt": "What makes interface design iterative and user-centred?", "answer": ["Designers involve users and evaluate ideas throughout development.", "Findings guide repeated changes to requirements, prototypes and interaction design."], "source": "Week 1 · PDF pp. 5–6, 63", "topic": "Design process", "origin": "lecture", "level": "application"}, {"id": "w2-s01", "type": "short", "group": "w2", "prompt": "List Norman’s seven stages in order.", "answer": ["Establish goal → form intention → decide sequence → execute sequence.", "Perceive state → interpret state → evaluate against the goal."], "source": "Week 2 · PDF p. 13", "topic": "Action cycle", "origin": "lecture", "level": "application"}, {"id": "w2-s02", "type": "short", "group": "w2", "prompt": "Distinguish the gulf of execution from the gulf of evaluation.", "answer": ["Execution is the gap between an intention and understanding how to act.", "Evaluation is the gap between the system state and understanding what happened."], "source": "Week 2 · PDF p. 14", "topic": "Action cycle", "origin": "lecture", "level": "application"}, {"id": "w2-s03", "type": "short", "group": "w2", "prompt": "A booking produces no confirmation. Identify the gulf and one improvement.", "answer": ["The gulf of evaluation increases because the user cannot understand the result.", "Show a noticeable confirmation with the booked details, or a specific error."], "source": "Week 2 · PDF pp. 13–14", "topic": "Application", "origin": "lecture", "level": "application"}, {"id": "w2-s04", "type": "short", "group": "w2", "prompt": "What is a mental model, and how can it be wrong?", "answer": ["A mental model is a user’s internal understanding of how a system works.", "It can be incomplete or mistaken, leading to inaccurate predictions."], "source": "Week 2 · PDF pp. 8–11, 19", "topic": "Mental models", "origin": "lecture", "level": "application"}, {"id": "w2-s05", "type": "short", "group": "w2", "prompt": "How does the system image communicate the intended model?", "answer": ["Users infer behaviour from the interface’s appearance, labels, instructions and responses.", "An unclear system image can produce a model that differs from the designer’s intention."], "source": "Week 2 · PDF pp. 15–17, 21", "topic": "Mental models", "origin": "lecture", "level": "application"}, {"id": "w2-s06", "type": "short", "group": "w2", "prompt": "Distinguish annotation from cognitive tracing.", "answer": ["Annotation adds marks to an existing representation, such as crossing off a task.", "Cognitive tracing rearranges external items, such as moving letter tiles."], "source": "Week 2 · PDF p. 29", "topic": "External cognition", "origin": "lecture", "level": "application"}, {"id": "w2-s07", "type": "short", "group": "w2", "prompt": "Explain why recognition is often easier than recall.", "answer": ["Recognition identifies information when it is presented; recall retrieves it without that cue.", "Visible menus and examples reduce demands on users’ memory."], "source": "Week 2 · PDF pp. 139, 145–146", "topic": "Memory", "origin": "lecture", "level": "application"}, {"id": "w2-s08", "type": "short", "group": "w2", "prompt": "Explain chunking and give an interface example.", "answer": ["Chunking groups information into meaningful units rather than separate items.", "Displaying a phone number in grouped digits makes it easier to process."], "source": "Week 2 · PDF pp. 142–146", "topic": "Memory", "origin": "lecture", "level": "application"}, {"id": "w2-s09", "type": "short", "group": "w2", "prompt": "Distinguish proximity from similarity.", "answer": ["Proximity groups elements by how close together they appear.", "Similarity groups elements by shared appearance, such as shape or styling."], "source": "Week 2 · PDF pp. 58–61", "topic": "Gestalt", "origin": "lecture", "level": "application"}, {"id": "w2-s10", "type": "short", "group": "w2", "prompt": "Distinguish inattentional blindness from change blindness.", "answer": ["Inattentional blindness means missing something while attention is occupied elsewhere.", "Change blindness means failing to notice a change in the environment or display."], "source": "Week 1 · PDF p. 46; Week 2 p. 127", "topic": "Attention", "origin": "lecture", "level": "application"}, {"id": "w2-s11", "type": "short", "group": "w2", "prompt": "Why should an error use more than colour?", "answer": ["Colour discrimination varies across users, object sizes and viewing conditions.", "Add a clear message or symbol so meaning does not depend on colour alone."], "source": "Week 2 · PDF pp. 110–114", "topic": "Colour", "origin": "lecture", "level": "application"}, {"id": "w2-s12", "type": "short", "group": "w2", "prompt": "Why do jargon and poor text presentation make interaction harder?", "answer": ["They can force effortful interpretation and burden working memory.", "Use readable text and concise, familiar wording that supports the task."], "source": "Week 2 · PDF pp. 149–160", "topic": "Reading", "origin": "lecture", "level": "application"}, {"id": "w3-s01", "type": "short", "group": "w3", "prompt": "Distinguish absolute from relative input.", "answer": ["Absolute input reports a position or value in a reference range.", "Relative input reports change from a previous position, as with mouse movement."], "source": "Week 3 · PDF p. 4", "topic": "Device taxonomy", "origin": "lecture", "level": "application"}, {"id": "w3-s02", "type": "short", "group": "w3", "prompt": "Distinguish direct from indirect input.", "answer": ["Direct input acts on the target, as when touching an on-screen control.", "Indirect input maps an action elsewhere to the target, as with a mouse."], "source": "Week 3 · PDF p. 5", "topic": "Device taxonomy", "origin": "lecture", "level": "application"}, {"id": "w3-s03", "type": "short", "group": "w3", "prompt": "What distinguishes binary from analog input?", "answer": ["Binary input supplies two states, such as pressed or not pressed.", "Analog input supplies a range of values, even if transmitted digitally."], "source": "Week 3 · PDF p. 6", "topic": "Device taxonomy", "origin": "lecture", "level": "application"}, {"id": "w3-s04", "type": "short", "group": "w3", "prompt": "Explain why a mouse and joystick suit different tasks.", "answer": ["A mouse supports precise relative pointing without automatic return to centre.", "A joystick’s centred tilt supports direction and rate control for continuous movement."], "source": "Week 3 · PDF pp. 11–16", "topic": "Devices", "origin": "lecture", "level": "application"}, {"id": "w3-s05", "type": "short", "group": "w3", "prompt": "Why can high-resolution phone screens still have poor touch usability?", "answer": ["Pixel resolution does not guarantee that controls are physically large enough.", "Small targets and finger occlusion can still produce selection errors."], "source": "Week 3 · PDF pp. 48–52", "topic": "Mobile input", "origin": "lecture", "level": "application"}, {"id": "w3-s06", "type": "short", "group": "w3", "prompt": "Distinguish accelerometers from gyroscopes.", "answer": ["An accelerometer measures acceleration, including gravity-related readings.", "A gyroscope measures angular velocity, the rate of rotation."], "source": "Week 3 · PDF pp. 18–19", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-s07", "type": "short", "group": "w3", "prompt": "Why does estimating position from acceleration drift?", "answer": ["Measurement noise accumulates when acceleration is integrated into velocity and position.", "Other sensor references can help reduce the resulting error."], "source": "Week 3 · PDF pp. 18–23", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-s08", "type": "short", "group": "w3", "prompt": "Explain sensor fusion with one example.", "answer": ["Sensor fusion combines readings to estimate information more reliably.", "Orientation can use accelerometer, gyroscope and magnetometer data together."], "source": "Week 3 · PDF p. 23", "topic": "Sensors", "origin": "lecture", "level": "application"}, {"id": "w3-s09", "type": "short", "group": "w3", "prompt": "What are six degrees of freedom?", "answer": ["They include movement along three spatial axes.", "They also include rotation around those three axes."], "source": "Week 3 · PDF p. 24", "topic": "Tracking", "origin": "lecture", "level": "application"}, {"id": "w3-s10", "type": "short", "group": "w3", "prompt": "Give two VR design concerns and an implication.", "answer": ["Motion sickness and physical injury risks affect comfortable, safe use.", "Adapt interaction and feedback to body movement and the surrounding space."], "source": "Week 3 · PDF pp. 31–34", "topic": "VR", "origin": "lecture", "level": "application"}, {"id": "w3-s11", "type": "short", "group": "w3", "prompt": "Why use event-based updates rather than continuous polling on mobile?", "answer": ["Repeated polling creates unnecessary processing and wake-ups.", "Event-based updates can help keep the processor idle and conserve energy."], "source": "Week 3 · PDF pp. 46–47", "topic": "Mobile constraints", "origin": "lecture", "level": "application"}, {"id": "w3-s12", "type": "short", "group": "w3", "prompt": "Why is mobile design more than resizing a desktop interface?", "answer": ["Mobile use differs in touch input, context, resources and short-session expectations.", "Prioritize common tasks, reduce typing and adapt controls to the available space."], "source": "Week 3 · PDF pp. 41–65", "topic": "Mobile constraints", "origin": "lecture", "level": "application"}, {"id": "w4-s01", "type": "short", "group": "w4", "prompt": "Distinguish functional and non-functional requirements.", "answer": ["Functional requirements state what the system should do.", "Non-functional requirements set qualities or constraints, such as response time."], "source": "Week 4 · PDF p. 17", "topic": "Requirements", "origin": "lecture", "level": "application"}, {"id": "w4-s02", "type": "short", "group": "w4", "prompt": "Name the three main categories of user requirements.", "answer": ["Identify user characteristics and user/business goals.", "Describe the physical, social, organizational and cultural context of use."], "source": "Week 4 · PDF pp. 15–18", "topic": "Requirements", "origin": "lecture", "level": "application"}, {"id": "w4-s03", "type": "short", "group": "w4", "prompt": "Explain the value of asking why a user requests a feature.", "answer": ["A feature request may describe one solution rather than the underlying goal.", "Understanding the goal lets designers compare alternative ways to support it."], "source": "Week 4 · PDF pp. 23–26", "topic": "Requirements", "origin": "lecture", "level": "application"}, {"id": "w4-s04", "type": "short", "group": "w4", "prompt": "Why choose a semi-structured interview?", "answer": ["Prepared questions cover important topics consistently.", "Flexible follow-up explores unexpected details and reasons."], "source": "Week 4 · PDF pp. 30–33", "topic": "Interviews", "origin": "lecture", "level": "application"}, {"id": "w4-s05", "type": "short", "group": "w4", "prompt": "Give one benefit and one limitation of think-aloud.", "answer": ["It reveals users’ beliefs, goals and reasons during a task.", "Speaking can feel unnatural and change task performance."], "source": "Week 4 · PDF p. 49", "topic": "Observation", "origin": "lecture", "level": "application"}, {"id": "w4-s06", "type": "short", "group": "w4", "prompt": "List the four contextual inquiry principles.", "answer": ["Context and partnership: study actual work collaboratively.", "Interpretation and focus: clarify meaning together while staying on the research question."], "source": "Week 4 · PDF pp. 55–56", "topic": "Contextual inquiry", "origin": "lecture", "level": "application"}, {"id": "w4-s07", "type": "short", "group": "w4", "prompt": "Explain triangulation.", "answer": ["Triangulation combines methods or data sources to investigate the same issue.", "Agreement supports findings; disagreement identifies questions needing further investigation."], "source": "Week 4 · PDF p. 61", "topic": "Research design", "origin": "lecture", "level": "application"}, {"id": "w4-s08", "type": "short", "group": "w4", "prompt": "What is wrong with “Was the interface clear and fast?”", "answer": ["It asks about two qualities in one answer, making the result ambiguous.", "Ask separately about clarity and speed using neutral wording."], "source": "Week 4 · PDF pp. 33, 39–43", "topic": "Bias", "origin": "lecture", "level": "application"}, {"id": "w4-s09", "type": "short", "group": "w4", "prompt": "What makes a persona useful and credible?", "answer": ["It synthesizes meaningful user characteristics and goals from actual research.", "It represents a relevant user group without idealizing them to fit the design."], "source": "Week 4 · PDF p. 66", "topic": "Personas", "origin": "lecture", "level": "application"}, {"id": "w4-s10", "type": "short", "group": "w4", "prompt": "Distinguish scenarios from use cases.", "answer": ["A scenario is one concrete narrative about activity in context.", "A use case structures actor–system interaction, including conditions and alternative paths."], "source": "Week 4 · PDF pp. 68–75", "topic": "Models", "origin": "lecture", "level": "application"}, {"id": "w4-s11", "type": "short", "group": "w4", "prompt": "Explain HTA and why it needs a plan.", "answer": ["HTA breaks an observable goal-directed activity into tasks and subtasks.", "Plans specify order, conditions and repetition; stop decomposing when further detail has little value."], "source": "Week 4 · PDF pp. 77–80", "topic": "HTA", "origin": "lecture", "level": "application"}, {"id": "w4-s12", "type": "short", "group": "w4", "prompt": "How does a state diagram differ from a task hierarchy?", "answer": ["A state diagram represents system conditions and transitions between them.", "A task hierarchy represents the structure of the user’s activity."], "source": "Week 4 · PDF pp. 77–82", "topic": "State diagrams", "origin": "lecture", "level": "application"}, {"id": "project-s01", "type": "short", "group": "project", "prompt": "What must the walkthrough demonstrate about the conceptual model?", "answer": ["Explain the core concepts, relationships and relevant metaphors.", "Use prototype callouts to show consistency, feedback and constraints."], "source": "Walkthrough brief · Conceptual model", "topic": "Assignment scope", "origin": "optional", "level": "application"}, {"id": "project-s02", "type": "short", "group": "project", "prompt": "What should the audience questionnaire contain?", "answer": ["At most seven closed-ended and two open-ended questions about the prototype.", "Build it in Google Forms and include its link with the submission."], "source": "Walkthrough brief · Questionnaire", "topic": "Questionnaire", "origin": "optional", "level": "application"}, {"id": "project-s03", "type": "short", "group": "project", "prompt": "Why distinguish findings from assumptions in the nutrition project?", "answer": ["Proposed users and features are hypotheses until evidence supports them.", "Use interviews and observed tasks to validate needs before claiming improvements."], "source": "Project outline + Week 4 · PDF pp. 20–26", "topic": "Design evidence", "origin": "optional", "level": "application"}, {"id": "project-s04", "type": "short", "group": "project", "prompt": "Outline one complex task for your nutrition-app prototype.", "answer": ["Request a meal suggestion, inspect it, and swap an unavailable ingredient.", "Save the adjusted meal to a plan and generate its shopping list."], "source": "Idea screenshot + proposed project outline", "topic": "Nutrition concept", "origin": "optional", "level": "application"}, {"id": "extra-s01", "type": "short", "group": "extra", "prompt": "Name the four cognitive walkthrough questions in the supplied photos.", "answer": ["Will the user pursue the right goal and notice the needed action?", "Will they connect the action to the goal and understand the feedback?"], "source": "Other professor · IMG_4845.JPG / IMG_4846.JPG", "topic": "Cognitive walkthrough", "origin": "optional", "level": "application"}, {"id": "extra-s02", "type": "short", "group": "extra", "prompt": "Evaluate David’s failed booking in the supplied walkthrough photo.", "answer": ["He wants to book, but hidden prerequisites and options make the action sequence unclear.", "Unexplained disabled controls and missing errors leave feedback inadequate."], "source": "Other professor · IMG_4846.JPG", "topic": "Cognitive walkthrough", "origin": "optional", "level": "application"}, {"id": "extra-s03", "type": "short", "group": "extra", "prompt": "Compute the sample KLM time: 3 P, 3 K, 1 M, 1 R; P=1.1, K=.2, M=1.35, R=.02 seconds.", "answer": ["T = 3(1.1) + 3(0.2) + 1.35 + 0.02.", "T = 5.27 seconds, assuming exactly the stated operators and one response interval."], "source": "Other professor · IMG_4843.JPG", "topic": "KLM", "origin": "optional", "level": "application"}, {"id": "extra-s04", "type": "short", "group": "extra", "prompt": "In the sample, why does a bar chart suit category comparison?", "answer": ["Bars display values for distinct categories side by side.", "Their lengths make differences between categories easy to compare."], "source": "Other professor · IMG_4848.JPG", "topic": "Evaluation extras", "origin": "optional", "level": "application"}, {"id": "context-s01", "type": "short", "group": "context", "prompt": "What is the excluded constructivist view of perception?", "answer": ["Perception combines information from the environment with previously stored knowledge.", "The experienced world is an interpretation, rather than a simple camera copy."], "source": "Week 2 · PDF pp. 66–70 · Not on test", "topic": "Constructivism", "origin": "optional", "level": "application"}, {"id": "context-s02", "type": "short", "group": "context", "prompt": "Give two sound-localization cues from the excluded slide.", "answer": ["Differences in sound level between ears provide one cue.", "Differences in arrival time between ears provide another."], "source": "Week 2 · PDF p. 86 · Not on test", "topic": "Sound localization", "origin": "optional", "level": "application"}, {"id": "w1-rm01", "group": "w1", "type": "mcq", "prompt": "An unlabeled door can be pushed, but visitors keep pulling. In Norman’s terminology, what most needs improvement?", "options": ["The signifier communicating how to act", "The door’s ability to move at all", "The building’s technical specification", "The visitors’ ability to form any goal"], "correct": 0, "explanation": "The action is possible; the cue communicating the correct action is inadequate.", "source": "Norman ch. 1 · Signifiers · Week 1 · PDF pp. 80–85", "readingRef": "Norman ch. 1 · Signifiers", "lectureRef": "Week 1 · PDF pp. 80–85", "book": "norman", "origin": "reading", "topic": "Affordances & signifiers", "level": "application"}, {"id": "w1-rm02", "group": "w1", "type": "mcq", "prompt": "In Norman’s account, how does an affordance differ from a signifier?", "options": ["An affordance makes an action possible; a signifier communicates where or how to act", "An affordance is always a written label; a signifier is always a hinge", "Both mean a confirmation after acting", "A signifier makes an action physically possible; an affordance only labels it"], "correct": 0, "explanation": "A cue and a possible action are related but distinct; a signifier can also indicate an unavailable action.", "source": "Norman ch. 1 · Fundamental Principles of Interaction · Week 1 · PDF pp. 80–81", "readingRef": "Norman ch. 1 · Fundamental Principles of Interaction", "lectureRef": "Week 1 · PDF pp. 80–81", "book": "norman", "origin": "reading", "topic": "Affordances & signifiers", "level": "concept"}, {"id": "w1-rm03", "group": "w1", "type": "mcq", "prompt": "A screen shows a button-shaped region that does nothing. What is the clearest diagnosis?", "options": ["Its appearance suggests an action the system does not provide", "The region must be a useful physical affordance", "Feedback is unnecessary because the control is visible", "All users need more training before clicking"], "correct": 0, "explanation": "The system image should accurately communicate available actions, rather than misleading users.", "source": "Norman ch. 1 · Signifiers and Conceptual Models · Week 1 · PDF pp. 60–61, 80–81", "readingRef": "Norman ch. 1 · Signifiers and Conceptual Models", "lectureRef": "Week 1 · PDF pp. 60–61, 80–81", "book": "norman", "origin": "reading", "topic": "Affordances & signifiers", "level": "application"}, {"id": "w1-rm04", "group": "w1", "type": "mcq", "prompt": "A user repeatedly submits because a request takes several seconds with no visible response. Which redesign is most direct?", "options": ["Show prompt acknowledgement and an understandable progress state", "Add more options to the submit menu", "Make the button look more decorative", "Hide the result until the user refreshes"], "correct": 0, "explanation": "Timely feedback acknowledges the action and helps prevent unnecessary repetition.", "source": "Norman ch. 1 · Feedback · Week 1 · PDF pp. 88–90", "readingRef": "Norman ch. 1 · Feedback", "lectureRef": "Week 1 · PDF pp. 88–90", "book": "norman", "origin": "reading", "topic": "Feedback", "level": "application"}, {"id": "w1-rm05", "group": "w1", "type": "mcq", "prompt": "A warning sounds for every minor event until users ignore it. What principle should guide improvement?", "options": ["Make feedback informative and proportionate to importance", "Increase every warning to maximum volume", "Remove every success and error indication", "Require users to memorize all hidden events"], "correct": 0, "explanation": "Feedback must communicate useful information without overloading or distracting the user.", "source": "Norman ch. 1 · Feedback · Week 1 · PDF pp. 88–90", "readingRef": "Norman ch. 1 · Feedback", "lectureRef": "Week 1 · PDF pp. 88–90", "book": "norman", "origin": "reading", "topic": "Feedback", "level": "application"}, {"id": "w1-rm06", "group": "w1", "type": "mcq", "prompt": "Four switches control four lights. Which arrangement best reduces the memory needed to choose a switch?", "options": ["A spatial arrangement matching the lights", "An unlabeled vertical row regardless of light positions", "Four identical buttons placed randomly", "A manual requiring memorization of a numeric code"], "correct": 0, "explanation": "Natural mapping puts the relationship in the layout rather than requiring recall.", "source": "Norman ch. 3 · Natural Mapping · Week 1 · PDF p. 87", "readingRef": "Norman ch. 3 · Natural Mapping", "lectureRef": "Week 1 · PDF p. 87", "book": "norman", "origin": "reading", "topic": "Mapping", "level": "application"}, {"id": "w1-rm07", "group": "w1", "type": "mcq", "prompt": "Which best expresses the relationship between usability and user experience in the textbook?", "options": ["They differ in emphasis but influence one another", "They are completely independent", "Usability concerns appearance alone", "Good experience guarantees accurate task completion"], "correct": 0, "explanation": "Task success and the felt experience should be considered together.", "source": "Interaction Design 6e · §1.9 · Week 1 · PDF pp. 70–78", "readingRef": "Interaction Design 6e · §1.9", "lectureRef": "Week 1 · PDF pp. 70–78", "book": "id", "origin": "reading", "topic": "Usability & UX", "level": "concept"}, {"id": "w1-rm08", "group": "w1", "type": "mcq", "prompt": "A game is deliberately challenging while a checkout is quick and predictable. What justifies the difference?", "options": ["Experience goals depend on the activity and context", "Efficiency never matters in games", "Challenge is always poor usability", "The checkout should imitate every game mechanic"], "correct": 0, "explanation": "A desirable experience for one activity may be inappropriate for another.", "source": "Interaction Design 6e · §1.9.2 · Week 1 · PDF p. 76", "readingRef": "Interaction Design 6e · §1.9.2", "lectureRef": "Week 1 · PDF p. 76", "book": "id", "origin": "reading", "topic": "Usability & UX", "level": "application"}, {"id": "w1-rm09", "group": "w1", "type": "mcq", "prompt": "A frequent user performs the wrong command after two adjacent buttons are swapped. What should the designer examine first?", "options": ["How the redesign disrupted a learned action", "Whether frequent use proves expert knowledge of every feature", "Whether the user should ignore all prior experience", "Whether swapping controls increased utility"], "correct": 0, "explanation": "Consistency supports habits; a change can turn existing skill into a source of error.", "source": "Norman ch. 5 · Two Types of Errors · Week 1 · PDF pp. 50–51, 97–98", "readingRef": "Norman ch. 5 · Two Types of Errors", "lectureRef": "Week 1 · PDF pp. 50–51, 97–98", "book": "norman", "origin": "reading", "topic": "Human error & consistency", "level": "application"}, {"id": "w1-rm10", "group": "w1", "type": "mcq", "prompt": "A person intends to click Save but accidentally clicks Delete. In Norman’s classification, what is this?", "options": ["A slip in executing an appropriate intention", "A mistake because the intended goal was deletion", "Proof that the system lacks all utility", "A correct action with no usability consequence"], "correct": 0, "explanation": "The intended action was appropriate, but the performed action differed from it.", "source": "Norman ch. 5 · Two Types of Errors: Slips and Mistakes · Week 1 · PDF pp. 43, 59–61; Week 2 p. 20", "readingRef": "Norman ch. 5 · Two Types of Errors: Slips and Mistakes", "lectureRef": "Week 1 · PDF pp. 43, 59–61; Week 2 p. 20", "book": "norman", "origin": "reading", "topic": "Human error", "level": "application"}, {"id": "w1-rm11", "group": "w1", "type": "mcq", "prompt": "A person deliberately deletes the only copy because they incorrectly believe another copy exists. What is the best classification?", "options": ["A mistake based on an incorrect plan or understanding", "An accidental click slip", "A successful goal evaluation", "A physical-input calibration problem"], "correct": 0, "explanation": "The action matches the plan; the plan rests on incorrect knowledge.", "source": "Norman ch. 5 · Two Types of Errors: Slips and Mistakes · Week 1 · PDF pp. 59–61; Week 2 p. 20", "readingRef": "Norman ch. 5 · Two Types of Errors: Slips and Mistakes", "lectureRef": "Week 1 · PDF pp. 59–61; Week 2 p. 20", "book": "norman", "origin": "reading", "topic": "Human error", "level": "application"}, {"id": "w1-rm12", "group": "w1", "type": "mcq", "prompt": "Which improvement most directly reduces a slip between neighbouring Save and Delete controls?", "options": ["Distinguish and separate the controls, with recovery for deletion", "Explain the entire database architecture", "Remove the visible task goal", "Require memorizing a longer navigation sequence"], "correct": 0, "explanation": "Prevent likely execution errors and support recovery rather than only telling users to be careful.", "source": "Norman ch. 5 · Designing for Error · Week 1 · PDF pp. 59–61, 96", "readingRef": "Norman ch. 5 · Designing for Error", "lectureRef": "Week 1 · PDF pp. 59–61, 96", "book": "norman", "origin": "reading", "topic": "Error prevention", "level": "application"}, {"id": "w1-rm13", "group": "w1", "type": "mcq", "prompt": "A connector physically fits in only the correct orientation. What provides the constraint?", "options": ["Its shape and physical compatibility", "A culturally learned colour meaning alone", "An error description appearing after insertion", "A fictional persona’s preference"], "correct": 0, "explanation": "Physical constraints limit possible actions through properties of the object.", "source": "Norman ch. 4 · Four Kinds of Constraints · Week 1 · PDF p. 96", "readingRef": "Norman ch. 4 · Four Kinds of Constraints", "lectureRef": "Week 1 · PDF p. 96", "book": "norman", "origin": "reading", "topic": "Constraints", "level": "application"}, {"id": "w1-rm14", "group": "w1", "type": "mcq", "prompt": "Why is “our interface follows every principle, so it must be usable” inadequate?", "options": ["Principles guide decisions but do not replace evaluation in context", "A principle dictates one exact layout for every task", "Usability cannot be examined with users", "Only visual polish determines usability"], "correct": 0, "explanation": "General principles help explain decisions; evidence is needed about their effects.", "source": "Interaction Design 6e · §1.9.3 · Week 1 · PDF pp. 72, 77", "readingRef": "Interaction Design 6e · §1.9.3", "lectureRef": "Week 1 · PDF pp. 72, 77", "book": "id", "origin": "reading", "topic": "Design evidence", "level": "application"}, {"id": "w1-rm15", "group": "w1", "type": "mcq", "prompt": "A confusing form tells the user “You did it wrong” without explaining the problem. What is a better response?", "options": ["Describe the specific issue and the corrective action", "Repeat the blame more forcefully", "Hide the error until another attempt", "Assume the user’s memory can supply missing instructions"], "correct": 0, "explanation": "Treat difficulties as design evidence and provide intelligible recovery information.", "source": "Norman ch. 2 · Blaming the Wrong Things · Week 1 · PDF pp. 59–61, 89–90", "readingRef": "Norman ch. 2 · Blaming the Wrong Things", "lectureRef": "Week 1 · PDF pp. 59–61, 89–90", "book": "norman", "origin": "reading", "topic": "Human error & feedback", "level": "application"}, {"id": "w1-rm16", "group": "w1", "type": "mcq", "prompt": "Why involve intended users when refining an interface?", "options": ["Their tasks, abilities and contexts can differ from the designers’ assumptions", "Users can always specify the final design without investigation", "One product owner represents every possible response", "User involvement removes the need for alternative designs"], "correct": 0, "explanation": "Real users provide evidence for requirements and evaluation throughout development.", "source": "Interaction Design 6e · §2.2.2 · Week 1 · PDF pp. 5–6, 63", "readingRef": "Interaction Design 6e · §2.2.2", "lectureRef": "Week 1 · PDF pp. 5–6, 63", "book": "id", "origin": "reading", "topic": "User-centred design", "level": "concept"}, {"id": "w2-rm01", "group": "w2", "type": "mcq", "prompt": "A user can see a control but cannot predict what clicking it will do. Which improvement helps bridge execution?", "options": ["Clarify its meaning and relationship to the goal", "Only display confirmation after the click", "Remove the task label", "Increase the number of hidden commands"], "correct": 0, "explanation": "Feedforward through signifiers and mappings helps users choose actions before performing them.", "source": "Norman ch. 2 · Seven Fundamental Design Principles · Week 2 · PDF pp. 13–14, 22", "readingRef": "Norman ch. 2 · Seven Fundamental Design Principles", "lectureRef": "Week 2 · PDF pp. 13–14, 22", "book": "norman", "origin": "reading", "topic": "Gulfs & action cycle", "level": "application"}, {"id": "w2-rm02", "group": "w2", "type": "mcq", "prompt": "Which statement distinguishes feedforward from feedback?", "options": ["Feedforward helps predict actions; feedback explains their results", "Feedforward reports only past results; feedback predicts actions", "Both mean a physical restriction on input", "Neither relates to a conceptual model"], "correct": 0, "explanation": "The two support the execution and evaluation sides of interaction.", "source": "Norman ch. 2 · Seven Fundamental Design Principles · Week 2 · PDF pp. 13–14, 21–22", "readingRef": "Norman ch. 2 · Seven Fundamental Design Principles", "lectureRef": "Week 2 · PDF pp. 13–14, 21–22", "book": "norman", "origin": "reading", "topic": "Gulfs & action cycle", "level": "concept"}, {"id": "w2-rm03", "group": "w2", "type": "mcq", "prompt": "The status “Pending” is visible, but the user thinks it means completed. Where is the main breakdown?", "options": ["Interpretation of the perceived state", "Physical execution of a mouse movement", "Failure to form any goal", "The presence of a correct spatial mapping"], "correct": 0, "explanation": "Noticing a state is different from correctly understanding its meaning.", "source": "Norman ch. 2 · The Seven Stages of Action · Week 2 · PDF pp. 13, 20", "readingRef": "Norman ch. 2 · The Seven Stages of Action", "lectureRef": "Week 2 · PDF pp. 13, 20", "book": "norman", "origin": "reading", "topic": "Gulfs & action cycle", "level": "application"}, {"id": "w2-rm04", "group": "w2", "type": "mcq", "prompt": "A user perceives and understands confirmation but never checks the appointment date. Which stage remains incomplete?", "options": ["Evaluation against the original goal", "Choosing an input device", "Initial perception of the confirmation", "Planning the action sequence"], "correct": 0, "explanation": "A successful-looking response must still be compared with the intended outcome.", "source": "Norman ch. 2 · The Seven Stages of Action · Week 2 · PDF pp. 13–14", "readingRef": "Norman ch. 2 · The Seven Stages of Action", "lectureRef": "Week 2 · PDF pp. 13–14", "book": "norman", "origin": "reading", "topic": "Gulfs & action cycle", "level": "application"}, {"id": "w2-rm05", "group": "w2", "type": "mcq", "prompt": "A thermostat user believes a higher target always makes heating faster. What does this illustrate?", "options": ["A mental model that predicts behaviour incorrectly", "An accurate model because the control has numbers", "An example of annotation", "Proof that more controls always improve feedback"], "correct": 0, "explanation": "Users’ inferred models can support mistaken predictions about system behaviour.", "source": "Interaction Design 6e · §4.3.1 · Week 2 · PDF pp. 8–12, 17–19", "readingRef": "Interaction Design 6e · §4.3.1", "lectureRef": "Week 2 · PDF pp. 8–12, 17–19", "book": "id", "origin": "reading", "topic": "Mental models", "level": "application"}, {"id": "w2-rm06", "group": "w2", "type": "mcq", "prompt": "What helps users correct an inaccurate mental model?", "options": ["Consistent explanations and system behaviour that reveal relevant relationships", "Expose every internal implementation detail regardless of relevance", "Change the same label’s meaning across screens", "Assume users already have the designer’s model"], "correct": 0, "explanation": "The system image should communicate an understandable, predictive model.", "source": "Norman ch. 1 · The System Image · Week 2 · PDF pp. 15–23", "readingRef": "Norman ch. 1 · The System Image", "lectureRef": "Week 2 · PDF pp. 15–23", "book": "norman", "origin": "reading", "topic": "Mental models", "level": "application"}, {"id": "w2-rm07", "group": "w2", "type": "mcq", "prompt": "A visible checklist allows a user to continue after an interruption. What is its cognitive value?", "options": ["It keeps task information in the world rather than requiring recall", "It makes working memory unlimited", "It prevents every interruption", "It guarantees that the user already knows each task"], "correct": 0, "explanation": "External reminders reduce memory demands and support resuming activity.", "source": "Norman ch. 3 · Knowledge in the Head and in the World · Week 2 · PDF pp. 26–29, 146", "readingRef": "Norman ch. 3 · Knowledge in the Head and in the World", "lectureRef": "Week 2 · PDF pp. 26–29, 146", "book": "norman", "origin": "reading", "topic": "External cognition", "level": "application"}, {"id": "w2-rm08", "group": "w2", "type": "mcq", "prompt": "Why is knowing the location of a reminder sometimes enough to support a task?", "options": ["The external cue can supply information when it is needed", "Every instruction must be memorized word for word", "Short-term memory permanently stores all reminders", "Recognizing information is impossible without recall"], "correct": 0, "explanation": "Knowledge can be distributed between memory and the visible environment.", "source": "Norman ch. 3 · The Tradeoff Between Knowledge in the World and in the Head · Week 2 · PDF pp. 28, 139–146", "readingRef": "Norman ch. 3 · The Tradeoff Between Knowledge in the World and in the Head", "lectureRef": "Week 2 · PDF pp. 28, 139–146", "book": "norman", "origin": "reading", "topic": "Recognition & recall", "level": "concept"}, {"id": "w2-rm09", "group": "w2", "type": "mcq", "prompt": "An interface displays 12 visible menu items. Why does “memory holds about seven, so this menu is invalid” not follow?", "options": ["Scanning visible choices is different from recalling unseen items", "Working memory has no limits", "All menus should contain exactly 12 items", "The principle applies only to numbers above 100"], "correct": 0, "explanation": "Memory-capacity findings are not a universal limit on visible options.", "source": "Interaction Design 6e · §4.2 · Memory · Week 2 · PDF pp. 142–146", "readingRef": "Interaction Design 6e · §4.2 · Memory", "lectureRef": "Week 2 · PDF pp. 142–146", "book": "id", "origin": "reading", "topic": "Memory", "level": "application"}, {"id": "w2-rm10", "group": "w2", "type": "mcq", "prompt": "Which explanation best connects grouping a long number to memory?", "options": ["Meaningful groups can be treated as chunks", "Adding separators guarantees permanent storage", "Every separated digit becomes a larger memory unit", "Chunking removes the need for perception"], "correct": 0, "explanation": "Chunking supports processing and remembering structured information.", "source": "Interaction Design 6e · §4.2 · Memory · Week 2 · PDF pp. 143–144", "readingRef": "Interaction Design 6e · §4.2 · Memory", "lectureRef": "Week 2 · PDF pp. 143–144", "book": "id", "origin": "reading", "topic": "Memory", "level": "concept"}, {"id": "w2-rm11", "group": "w2", "type": "mcq", "prompt": "A display adds several animations to ensure an important update is seen. What can go wrong?", "options": ["Competing stimuli can divert attention from the important update", "Animation always guarantees attention to the intended item", "Every visual cue becomes equally salient", "Divided attention eliminates cognitive limits"], "correct": 0, "explanation": "Attention cues must be selective and relevant rather than cluttering the display.", "source": "Interaction Design 6e · §4.2 · Attention · Week 2 · PDF pp. 122–136", "readingRef": "Interaction Design 6e · §4.2 · Attention", "lectureRef": "Week 2 · PDF pp. 122–136", "book": "id", "origin": "reading", "topic": "Attention", "level": "application"}, {"id": "w2-rm12", "group": "w2", "type": "mcq", "prompt": "Users recognize an icon in the usual toolbar but struggle when it moves elsewhere. Which explanation fits?", "options": ["Context and expectations influence recognition and retrieval", "Memory is independent of presentation context", "All icons have physically fixed meanings", "The interface has become an absolute input device"], "correct": 0, "explanation": "Familiar context helps users find and interpret information.", "source": "Interaction Design 6e · §4.2 · Memory · Week 2 · PDF pp. 123, 141–146", "readingRef": "Interaction Design 6e · §4.2 · Memory", "lectureRef": "Week 2 · PDF pp. 123, 141–146", "book": "id", "origin": "reading", "topic": "Memory & context", "level": "application"}, {"id": "w2-rm13", "group": "w2", "type": "mcq", "prompt": "Why is reflective practice more useful than passively rereading a definition?", "options": ["Applying and connecting its meaning supports deeper encoding", "Reading never produces memory", "Only pictures can be encoded", "Working memory automatically becomes larger"], "correct": 0, "explanation": "Attention and meaningful processing affect what is retained.", "source": "Interaction Design 6e · §4.2 · Memory and Learning · Week 2 · PDF pp. 139–140", "readingRef": "Interaction Design 6e · §4.2 · Memory and Learning", "lectureRef": "Week 2 · PDF pp. 139–140", "book": "id", "origin": "reading", "topic": "Learning", "level": "concept"}, {"id": "w2-rm14", "group": "w2", "type": "mcq", "prompt": "A user reads the same unfamiliar abbreviation repeatedly to understand a sentence. What would most directly help?", "options": ["Replace it with familiar, concise wording", "Increase the number of abbreviations", "Rely on a patterned background to attract attention", "Require the user to remember the acronym before using the system"], "correct": 0, "explanation": "Unnecessary decoding competes with understanding the task’s meaning.", "source": "Interaction Design 6e · §4.2 · Reading, Speaking, and Listening · Week 2 · PDF pp. 149–160", "readingRef": "Interaction Design 6e · §4.2 · Reading, Speaking, and Listening", "lectureRef": "Week 2 · PDF pp. 149–160", "book": "id", "origin": "reading", "topic": "Reading", "level": "application"}, {"id": "w2-rm15", "group": "w2", "type": "mcq", "prompt": "A diagram makes a comparison visible instead of requiring mental calculation. What is this an example of?", "options": ["Computational offloading through an external representation", "Making the user’s mental model technically complete", "Increasing the number of hidden steps", "Removing the need to interpret any information"], "correct": 0, "explanation": "External representations can reduce internal processing effort.", "source": "Interaction Design 6e · §4.3.5 · Week 2 · PDF pp. 26–36", "readingRef": "Interaction Design 6e · §4.3.5", "lectureRef": "Week 2 · PDF pp. 26–36", "book": "id", "origin": "reading", "topic": "External cognition", "level": "application"}, {"id": "w2-rm16", "group": "w2", "type": "mcq", "prompt": "Why can experts make a familiar-action error after a control changes?", "options": ["A learned sequence may run with little conscious attention", "Experts do not form mental models", "Experts have no memory limitations at all", "Every expert action is slow and deliberate"], "correct": 0, "explanation": "Established automatic behaviour can become inappropriate after an interface change.", "source": "Norman ch. 5 · The Classification of Slips · Week 2 · PDF pp. 43–46; Week 1 pp. 50–51", "readingRef": "Norman ch. 5 · The Classification of Slips", "lectureRef": "Week 2 · PDF pp. 43–46; Week 1 pp. 50–51", "book": "norman", "origin": "reading", "topic": "Automatic processing", "level": "application"}, {"id": "w3-rm01", "group": "w3", "type": "mcq", "prompt": "A phone form replaces tiny adjacent icons with larger labelled controls. Which difficulty does this address?", "options": ["Touch precision and identifying the intended action", "The gyroscope’s angular drift", "The lack of geographic coordinates", "The difference between two network protocols"], "correct": 0, "explanation": "Touch targets need usable physical size and clear meaning, not just more pixels.", "source": "Interaction Design 6e · §7.2.6 · Week 3 · PDF pp. 48–52", "readingRef": "Interaction Design 6e · §7.2.6", "lectureRef": "Week 3 · PDF pp. 48–52", "book": "id", "origin": "reading", "topic": "Touch input", "level": "application"}, {"id": "w3-rm02", "group": "w3", "type": "mcq", "prompt": "An essential gesture has no visible cue. What is a likely first-time-user problem?", "options": ["The action may be undiscoverable despite being supported", "The touchscreen cannot sense any input", "Every gesture is easier than a labelled button", "The phone must have a neutral spring position"], "correct": 0, "explanation": "Input capability alone does not communicate which action to perform.", "source": "Norman ch. 1 · Signifiers; Interaction Design 6e · §7.2.10 · Week 1 · PDF p. 81; Week 3 pp. 51–52", "readingRef": "Norman ch. 1 · Signifiers; Interaction Design 6e · §7.2.10", "lectureRef": "Week 1 · PDF p. 81; Week 3 pp. 51–52", "book": "norman", "origin": "reading", "topic": "Discoverability", "level": "application"}, {"id": "w3-rm03", "group": "w3", "type": "mcq", "prompt": "Why is a desktop hover-only explanation unreliable on a phone?", "options": ["Touch use may not provide the same hover interaction", "Phones lack all graphical interfaces", "High resolution creates a mouse cursor automatically", "Every mobile user carries a stylus"], "correct": 0, "explanation": "Ported interfaces must accommodate the input interactions actually available.", "source": "Interaction Design 6e · §7.2.6–7.2.10 · Week 3 · PDF pp. 51–52, 64", "readingRef": "Interaction Design 6e · §7.2.6–7.2.10", "lectureRef": "Week 3 · PDF pp. 51–52, 64", "book": "id", "origin": "reading", "topic": "Mobile adaptation", "level": "application"}, {"id": "w3-rm04", "group": "w3", "type": "mcq", "prompt": "A finger hides the item being dragged. Which design issue is illustrated?", "options": ["Occlusion during direct touch manipulation", "A GPS position error", "A binary-to-analog conversion failure", "A change in organizational hierarchy"], "correct": 0, "explanation": "Direct input can feel natural while obscuring the object under the finger.", "source": "Interaction Design 6e · §7.2.10 · Week 3 · PDF pp. 48, 52", "readingRef": "Interaction Design 6e · §7.2.10", "lectureRef": "Week 3 · PDF pp. 48, 52", "book": "id", "origin": "reading", "topic": "Touch input", "level": "application"}, {"id": "w3-rm05", "group": "w3", "type": "mcq", "prompt": "Which is a defensible way to select an input method?", "options": ["Match precision, environment and user capabilities to the task", "Assume the newest method is always the most usable", "Use touch for every task regardless of accuracy", "Choose based only on device appearance"], "correct": 0, "explanation": "Interface choice depends on the intended activity and context.", "source": "Interaction Design 6e · §7.4 · Week 3 · PDF pp. 2–5", "readingRef": "Interaction Design 6e · §7.4", "lectureRef": "Week 3 · PDF pp. 2–5", "book": "id", "origin": "reading", "topic": "Device selection", "level": "concept"}, {"id": "w3-rm06", "group": "w3", "type": "mcq", "prompt": "A drawing task needs precise freehand strokes. Why might pen input suit it?", "options": ["It can use familiar drawing skills and precise contact", "It eliminates every learning requirement", "It always works without any compatible hardware", "It makes all feedback unnecessary"], "correct": 0, "explanation": "Pen-based interaction can capitalize on practised writing and drawing skills.", "source": "Interaction Design 6e · §7.2.9 · Week 3 · PDF pp. 5, 13, 25", "readingRef": "Interaction Design 6e · §7.2.9", "lectureRef": "Week 3 · PDF pp. 5, 13, 25", "book": "id", "origin": "reading", "topic": "Pen input", "level": "application"}, {"id": "w3-rm07", "group": "w3", "type": "mcq", "prompt": "A user must hear private food entries spoken in a crowded room. What is the relevant concern?", "options": ["The suitability of voice output in the social and physical context", "Voice is unsuitable for every possible user", "The display’s colour model alone", "Whether the accelerometer has a neutral position"], "correct": 0, "explanation": "An input or output method must be evaluated in its actual environment.", "source": "Interaction Design 6e · §7.2.8; §11.3.1 · Week 3 · PDF pp. 26–27, 51; Week 4 p. 18", "readingRef": "Interaction Design 6e · §7.2.8; §11.3.1", "lectureRef": "Week 3 · PDF pp. 26–27, 51; Week 4 p. 18", "book": "id", "origin": "reading", "topic": "Voice & context", "level": "application"}, {"id": "w3-rm08", "group": "w3", "type": "mcq", "prompt": "A voice system repeatedly mishears a request. What most helps recovery?", "options": ["Explain the difficulty and offer clarification or another way to proceed", "Repeat the same long menu without an exit", "Require the user to guess an undocumented phrase", "Treat speech recognition as error-free"], "correct": 0, "explanation": "Voice interaction needs clear prompts, recovery and escape options.", "source": "Interaction Design 6e · §7.2.8 · Week 3 · PDF pp. 26–27; Week 1 pp. 88–90", "readingRef": "Interaction Design 6e · §7.2.8", "lectureRef": "Week 3 · PDF pp. 26–27; Week 1 pp. 88–90", "book": "id", "origin": "reading", "topic": "Voice feedback", "level": "application"}, {"id": "w3-rm09", "group": "w3", "type": "mcq", "prompt": "A watch briefly vibrates for a relevant event. What kind of feedback is provided?", "options": ["Haptic feedback", "An absolute geographic coordinate", "A visual affordance only", "A keyboard keystroke"], "correct": 0, "explanation": "Haptics communicate through touch, vibration or force.", "source": "Interaction Design 6e · §7.2.12 · Week 3 · PDF p. 25", "readingRef": "Interaction Design 6e · §7.2.12", "lectureRef": "Week 3 · PDF p. 25", "book": "id", "origin": "reading", "topic": "Haptics", "level": "concept"}, {"id": "w3-rm10", "group": "w3", "type": "mcq", "prompt": "Why can continuous vibration become a poor notification strategy?", "options": ["It can annoy users and lose effectiveness through habituation", "It guarantees comprehension of every message", "It removes the need for other information", "It makes the device a 3D tracker"], "correct": 0, "explanation": "Feedback should occur at appropriate moments and intensities.", "source": "Interaction Design 6e · §7.2.12 · Week 3 · PDF p. 25; Week 2 pp. 123, 133–136", "readingRef": "Interaction Design 6e · §7.2.12", "lectureRef": "Week 3 · PDF p. 25; Week 2 pp. 123, 133–136", "book": "id", "origin": "reading", "topic": "Haptics & attention", "level": "application"}, {"id": "w3-rm11", "group": "w3", "type": "mcq", "prompt": "An app combines readable text with a relevant vibration. What is the benefit to examine?", "options": ["Whether different output channels help users notice and understand the event", "Whether more channels automatically guarantee better usability", "Whether every user has identical sensory abilities", "Whether text and vibration remove context differences"], "correct": 0, "explanation": "Combining modalities can help, but the specific combination still requires evaluation.", "source": "Interaction Design 6e · §7.2.13 · Week 2 · PDF pp. 82, 135; Week 3 pp. 25–27", "readingRef": "Interaction Design 6e · §7.2.13", "lectureRef": "Week 2 · PDF pp. 82, 135; Week 3 pp. 25–27", "book": "id", "origin": "reading", "topic": "Multiple feedback channels", "level": "application"}, {"id": "w3-rm12", "group": "w3", "type": "mcq", "prompt": "What distinguishes a VR design concern from ordinary flat-screen layout alone?", "options": ["Head and body movement, surrounding space and comfort affect interaction", "Every status label must stay at the bottom corner", "Physical safety no longer matters", "A headset removes all input differences"], "correct": 0, "explanation": "Immersive interaction changes viewing and physical-use conditions.", "source": "Interaction Design 6e · §7.2.4 · Week 3 · PDF pp. 30–35", "readingRef": "Interaction Design 6e · §7.2.4", "lectureRef": "Week 3 · PDF pp. 30–35", "book": "id", "origin": "reading", "topic": "Virtual reality", "level": "concept"}, {"id": "w3-rm13", "group": "w3", "type": "mcq", "prompt": "A VR user needs status about the object they are handling. Which design is worth testing?", "options": ["Place meaningful feedback near the relevant object", "Always keep it in a distant corner regardless of viewing effort", "Hide it until the session ends", "Display every application’s status simultaneously"], "correct": 0, "explanation": "Feedback location should support comfortable, task-relevant viewing.", "source": "Interaction Design 6e · §7.2.4 · Week 3 · PDF p. 34", "readingRef": "Interaction Design 6e · §7.2.4", "lectureRef": "Week 3 · PDF p. 34", "book": "id", "origin": "reading", "topic": "Virtual reality", "level": "application"}, {"id": "w3-rm14", "group": "w3", "type": "mcq", "prompt": "Why prioritize a phone’s common task rather than show every possible feature at once?", "options": ["Small displays and short sessions make relevant information and actions important", "Mobile devices cannot support any complex task", "Desktop users never need prioritization", "A smaller font solves every space constraint"], "correct": 0, "explanation": "Prioritization should support the user’s goal without unnecessary search or clutter.", "source": "Interaction Design 6e · §7.2.6 · Week 3 · PDF pp. 50, 56–62", "readingRef": "Interaction Design 6e · §7.2.6", "lectureRef": "Week 3 · PDF pp. 50, 56–62", "book": "id", "origin": "reading", "topic": "Mobile usage", "level": "application"}, {"id": "w3-rm15", "group": "w3", "type": "mcq", "prompt": "A phone displays frequent offers whenever the user changes location. What should be investigated?", "options": ["Relevance, interruption and user control over notifications", "Whether GPS proves the user wants every offer", "Whether more alerts necessarily mean more satisfaction", "Whether disabling alert controls improves learnability"], "correct": 0, "explanation": "Context-aware capabilities do not establish that proactive interruptions are desirable.", "source": "Interaction Design 6e · §7.2.6 · Week 3 · PDF pp. 20, 55–56", "readingRef": "Interaction Design 6e · §7.2.6", "lectureRef": "Week 3 · PDF pp. 20, 55–56", "book": "id", "origin": "reading", "topic": "Mobile notifications", "level": "application"}, {"id": "w3-rm16", "group": "w3", "type": "mcq", "prompt": "Which claim best connects direct input to usability?", "options": ["Touching a target can reduce indirect mapping, but precision and occlusion still matter", "Direct input is always superior to every indirect device", "Direct input guarantees novice success", "All direct input is binary"], "correct": 0, "explanation": "Natural-feeling input still has task-specific limitations.", "source": "Interaction Design 6e · §7.2.10; Norman ch. 1 · Signifiers · Week 3 · PDF pp. 5, 13, 48–52", "readingRef": "Interaction Design 6e · §7.2.10; Norman ch. 1 · Signifiers", "lectureRef": "Week 3 · PDF pp. 5, 13, 48–52", "book": "id", "origin": "reading", "topic": "Direct input trade-offs", "level": "concept"}, {"id": "w4-rm01", "group": "w4", "type": "mcq", "prompt": "A client requests a new button, but observation reveals a repeated workaround. What should requirements work establish first?", "options": ["The underlying task and problem the button is meant to address", "The button’s final colour before considering the task", "A guarantee that the requested solution is correct", "Only whether competitors have the same button"], "correct": 0, "explanation": "Investigate the problem before committing to one proposed solution.", "source": "Norman ch. 6 · Solving the Correct Problem · Week 4 · PDF pp. 23–26", "readingRef": "Norman ch. 6 · Solving the Correct Problem", "lectureRef": "Week 4 · PDF pp. 23–26", "book": "norman", "origin": "reading", "topic": "Requirements discovery", "level": "application"}, {"id": "w4-rm02", "group": "w4", "type": "mcq", "prompt": "Why can requirements change after users see a prototype?", "options": ["Interaction can reveal needs and misunderstandings not evident initially", "Requirements work should never involve users", "A prototype proves every initial assumption true", "Only implementation bugs can alter requirements"], "correct": 0, "explanation": "Requirements, design and evaluation inform one another iteratively.", "source": "Interaction Design 6e · §11.2.1 · Week 4 · PDF pp. 8, 20", "readingRef": "Interaction Design 6e · §11.2.1", "lectureRef": "Week 4 · PDF pp. 8, 20", "book": "id", "origin": "reading", "topic": "Iterative requirements", "level": "concept"}, {"id": "w4-rm03", "group": "w4", "type": "mcq", "prompt": "A requirement says “easy to learn.” Which revision makes success more assessable?", "options": ["Specify the user group, task, allowed help and measurable completion criterion", "Replace it with “very intuitive”", "Specify only the logo design", "Ask whether the developer likes it"], "correct": 0, "explanation": "A fit criterion turns a vague goal into something that can be evaluated.", "source": "Interaction Design 6e · §11.2.2–11.3 · Week 4 · PDF pp. 8, 17", "readingRef": "Interaction Design 6e · §11.2.2–11.3", "lectureRef": "Week 4 · PDF pp. 8, 17", "book": "id", "origin": "reading", "topic": "Measurable requirements", "level": "application"}, {"id": "w4-rm04", "group": "w4", "type": "mcq", "prompt": "“The displayed stock price must be current within a defined interval” addresses what?", "options": ["A quality of the required data", "Only the ability to search a symbol", "The user’s educational level", "A persona’s fictional identity"], "correct": 0, "explanation": "Data requirements concern characteristics such as accuracy, freshness and persistence.", "source": "Interaction Design 6e · §11.3.1 · Week 4 · PDF p. 17", "readingRef": "Interaction Design 6e · §11.3.1", "lectureRef": "Week 4 · PDF p. 17", "book": "id", "origin": "reading", "topic": "Functional & non-functional", "level": "application"}, {"id": "w4-rm05", "group": "w4", "type": "mcq", "prompt": "A system will be operated wearing gloves in a noisy workshop. What must requirements consider?", "options": ["Input and feedback suited to the physical environment", "Only the number of job roles", "Only the database colour theme", "Whether all users have the same name"], "correct": 0, "explanation": "Context determines whether touch, audio and other interaction mechanisms work effectively.", "source": "Interaction Design 6e · §11.3.1 · Week 4 · PDF p. 18", "readingRef": "Interaction Design 6e · §11.3.1", "lectureRef": "Week 4 · PDF p. 18", "book": "id", "origin": "reading", "topic": "Context of use", "level": "application"}, {"id": "w4-rm06", "group": "w4", "type": "mcq", "prompt": "What should guide participant selection for a requirements study?", "options": ["The study goal and intended user characteristics", "Convenience alone, regardless of who uses the product", "Only people who agree with the designer", "The most technically skilled people for every task"], "correct": 0, "explanation": "A study needs participants relevant to the question being investigated.", "source": "Interaction Design 6e · §8.2.1–8.2.2 · Week 4 · PDF pp. 16, 33, 61", "readingRef": "Interaction Design 6e · §8.2.1–8.2.2", "lectureRef": "Week 4 · PDF pp. 16, 33, 61", "book": "id", "origin": "reading", "topic": "Research design", "level": "concept"}, {"id": "w4-rm07", "group": "w4", "type": "mcq", "prompt": "Two people have the same job title but different goals and work routines. What follows for personas?", "options": ["Relevant goals and behaviour may distinguish them despite similar demographics", "They must be represented by an identical persona", "Job titles fully determine every interaction need", "Their differences should be removed from the requirements"], "correct": 0, "explanation": "Personas synthesize meaningful goals and behaviour, not just demographic categories.", "source": "Interaction Design 6e · §11.5.1 · Week 4 · PDF pp. 66–67", "readingRef": "Interaction Design 6e · §11.5.1", "lectureRef": "Week 4 · PDF pp. 66–67", "book": "id", "origin": "reading", "topic": "Personas", "level": "application"}, {"id": "w4-rm08", "group": "w4", "type": "mcq", "prompt": "A team invents a convenient “typical user” without investigation. How should it be treated?", "options": ["As a provisional assumption to validate, not a research finding", "As evidence of the whole user population", "As a replacement for all interviews", "As a guaranteed accurate mental model"], "correct": 0, "explanation": "Credible personas derive from user data; assumptions should remain identifiable.", "source": "Interaction Design 6e · §11.5.1 · Week 4 · PDF p. 66", "readingRef": "Interaction Design 6e · §11.5.1", "lectureRef": "Week 4 · PDF p. 66", "book": "id", "origin": "reading", "topic": "Personas", "level": "application"}, {"id": "w4-rm09", "group": "w4", "type": "mcq", "prompt": "An interview guide contains questions that participants interpret differently. What should the team do before the main study?", "options": ["Pilot and revise the questions for clarity", "Increase sample size without fixing the questions", "Use longer jargon-heavy wording", "Assume ambiguous answers can always be interpreted later"], "correct": 0, "explanation": "A pilot helps uncover procedural and question problems before full data gathering.", "source": "Interaction Design 6e · §8.2.6 · Week 4 · PDF pp. 33, 39–43, 61", "readingRef": "Interaction Design 6e · §8.2.6", "lectureRef": "Week 4 · PDF pp. 33, 39–43, 61", "book": "id", "origin": "reading", "topic": "Research design", "level": "application"}, {"id": "w4-rm10", "group": "w4", "type": "mcq", "prompt": "Survey choices use ages 18–25 and 25–35. What is the immediate problem?", "options": ["A 25-year-old belongs to two overlapping categories", "Every range must have exactly equal width", "Age questions can never be closed-ended", "The response is automatically a ratio scale"], "correct": 0, "explanation": "Response categories should avoid overlap and fit the information needed.", "source": "Interaction Design 6e · §8.5.2 · Week 4 · PDF pp. 40–43", "readingRef": "Interaction Design 6e · §8.5.2", "lectureRef": "Week 4 · PDF pp. 40–43", "book": "id", "origin": "reading", "topic": "Questionnaire design", "level": "application"}, {"id": "w4-rm11", "group": "w4", "type": "mcq", "prompt": "Why provide an appropriate “not applicable” or “no opinion” option?", "options": ["To avoid forcing an answer that misrepresents the respondent", "To make every participant skip all questions", "To remove the need for neutral wording", "To guarantee a high response rate"], "correct": 0, "explanation": "Closed responses need options that accurately accommodate participants’ situations.", "source": "Interaction Design 6e · §8.5.2 · Week 4 · PDF pp. 39–43", "readingRef": "Interaction Design 6e · §8.5.2", "lectureRef": "Week 4 · PDF pp. 39–43", "book": "id", "origin": "reading", "topic": "Questionnaire design", "level": "concept"}, {"id": "w4-rm12", "group": "w4", "type": "mcq", "prompt": "Users say a task is easy but observation shows repeated failed attempts. What is the best response?", "options": ["Investigate the difference between reported experience and observed behaviour", "Discard observations because opinions are always correct", "Treat one method as automatically infallible", "Average the sentences into a task-completion time"], "correct": 0, "explanation": "Triangulation can reveal disagreement worth investigating rather than hiding.", "source": "Interaction Design 6e · §8.2.5 · Week 4 · PDF pp. 46–49, 61", "readingRef": "Interaction Design 6e · §8.2.5", "lectureRef": "Week 4 · PDF pp. 46–49, 61", "book": "id", "origin": "reading", "topic": "Triangulation", "level": "application"}, {"id": "w4-rm13", "group": "w4", "type": "mcq", "prompt": "Which interview behaviour best protects the value of the participant’s account?", "options": ["Use neutral follow-up and ask for concrete details", "Explain why the participant should like the prototype", "Finish every answer for the participant", "Ask several unrelated questions in one sentence"], "correct": 0, "explanation": "Listening and neutral probing reduce the interviewer’s influence on answers.", "source": "Interaction Design 6e · §8.4 · Week 4 · PDF pp. 30–33", "readingRef": "Interaction Design 6e · §8.4", "lectureRef": "Week 4 · PDF pp. 30–33", "book": "id", "origin": "reading", "topic": "Interviewing", "level": "application"}, {"id": "w4-rm14", "group": "w4", "type": "mcq", "prompt": "Which makes a use case more useful for evaluating a form?", "options": ["Include invalid-input and recovery paths as well as successful completion", "List only the screen’s colours", "Assume every entry is valid", "Replace the actor’s goal with the database name"], "correct": 0, "explanation": "Alternative paths make error handling and task recovery explicit.", "source": "Interaction Design 6e · §11.6 · Week 4 · PDF pp. 70–75", "readingRef": "Interaction Design 6e · §11.6", "lectureRef": "Week 4 · PDF pp. 70–75", "book": "id", "origin": "reading", "topic": "Use cases", "level": "application"}, {"id": "w4-rm15", "group": "w4", "type": "mcq", "prompt": "Why use an essential use case before deciding on widgets?", "options": ["It separates the user’s intention from a particular interface implementation", "It specifies the exact pixel position of every button", "It replaces the need to know the task goal", "It is a complete executable prototype"], "correct": 0, "explanation": "Intentions and responsibilities allow different designs to be compared.", "source": "Interaction Design 6e · §11.6 · Week 4 · PDF p. 75", "readingRef": "Interaction Design 6e · §11.6", "lectureRef": "Week 4 · PDF p. 75", "book": "id", "origin": "reading", "topic": "Essential use cases", "level": "concept"}, {"id": "w4-rm16", "group": "w4", "type": "mcq", "prompt": "A workflow includes checking paper packaging before entering a value. Should task analysis include it?", "options": ["Yes, relevant activity can occur outside the interface", "No, only mouse clicks count as tasks", "No, physical actions cannot affect requirements", "Only if the packaging is already digitized"], "correct": 0, "explanation": "Task-centred inquiry studies how the goal is achieved, including external artifacts and actions.", "source": "Norman ch. 6 · Observation; Interaction Design 6e · §11.4 · Week 4 · PDF pp. 76–79", "readingRef": "Norman ch. 6 · Observation; Interaction Design 6e · §11.4", "lectureRef": "Week 4 · PDF pp. 76–79", "book": "norman", "origin": "reading", "topic": "Task analysis", "level": "application"}, {"id": "w1-rs01", "group": "w1", "type": "short", "prompt": "A door can be pushed but has a misleading pull handle. Use Norman’s distinction to explain the failure.", "answer": ["The door affords opening, but the handle signifies an inappropriate pulling action.", "Use a clear push surface or cue that matches the permitted action."], "keyPoints": ["Action versus cue", "Cue should match permitted action"], "source": "Norman ch. 1 · Affordances and Signifiers · Week 1 · PDF pp. 80–85", "readingRef": "Norman ch. 1 · Affordances and Signifiers", "lectureRef": "Week 1 · PDF pp. 80–85", "book": "norman", "origin": "reading", "topic": "Affordances & signifiers", "level": "application"}, {"id": "w1-rs02", "group": "w1", "type": "short", "prompt": "A form is usable in some respects but users cannot undo accidental deletion. Identify a goal and improvement.", "answer": ["Safety is weak because an execution error has a harmful consequence.", "Provide an appropriate undo or recovery mechanism and distinguish the destructive control."], "keyPoints": ["Safety / error consequence", "Recover or prevent deletion"], "source": "Interaction Design 6e · §1.9.1; Norman ch. 5 · Designing for Error · Week 1 · PDF pp. 73, 96", "readingRef": "Interaction Design 6e · §1.9.1; Norman ch. 5 · Designing for Error", "lectureRef": "Week 1 · PDF pp. 73, 96", "book": "id", "origin": "reading", "topic": "Safety", "level": "application"}, {"id": "w1-rs03", "group": "w1", "type": "short", "prompt": "Explain a slip versus a mistake using two brief examples.", "answer": ["A slip is intending Save but accidentally clicking Delete.", "A mistake is intentionally deleting because an incorrect plan assumes another copy exists."], "keyPoints": ["Execution differs from intention", "Wrong goal / plan / understanding"], "source": "Norman ch. 5 · Two Types of Errors · Week 1 · PDF pp. 59–61; Week 2 p. 20", "readingRef": "Norman ch. 5 · Two Types of Errors", "lectureRef": "Week 1 · PDF pp. 59–61; Week 2 p. 20", "book": "norman", "origin": "reading", "topic": "Human error", "level": "application"}, {"id": "w1-rs04", "group": "w1", "type": "short", "prompt": "A slow submission gives no response, and users click repeatedly. Give a principle-based fix.", "answer": ["Missing feedback leaves users unsure whether the action was accepted.", "Acknowledge submission promptly and display meaningful progress, completion or failure."], "keyPoints": ["Identify feedback problem", "Communicate action and result"], "source": "Norman ch. 1 · Feedback · Week 1 · PDF pp. 88–90", "readingRef": "Norman ch. 1 · Feedback", "lectureRef": "Week 1 · PDF pp. 88–90", "book": "norman", "origin": "reading", "topic": "Feedback", "level": "application"}, {"id": "w1-rs05", "group": "w1", "type": "short", "prompt": "Why can a beautiful interface still be unsuitable for its users?", "answer": ["Appearance does not establish that users can accomplish their tasks effectively.", "Evaluate task success and experience against the intended users, goals and context."], "keyPoints": ["Appearance does not prove usability", "Evaluate actual task and context"], "source": "Interaction Design 6e · §1.9 · Week 1 · PDF pp. 70–78", "readingRef": "Interaction Design 6e · §1.9", "lectureRef": "Week 1 · PDF pp. 70–78", "book": "id", "origin": "reading", "topic": "Usability & UX", "level": "application"}, {"id": "w1-rs06", "group": "w1", "type": "short", "prompt": "Four controls are arranged differently from the four objects they operate. Explain a redesign.", "answer": ["Poor mapping forces users to learn or recall which control affects each object.", "Arrange or label controls to make the control–effect relationship clear."], "keyPoints": ["Mapping / memory demand", "Clear correspondence"], "source": "Norman ch. 3 · Natural Mapping · Week 1 · PDF p. 87", "readingRef": "Norman ch. 3 · Natural Mapping", "lectureRef": "Week 1 · PDF p. 87", "book": "norman", "origin": "reading", "topic": "Mapping", "level": "application"}, {"id": "w1-rs07", "group": "w1", "type": "short", "prompt": "How should design address repeated errors made by different users?", "answer": ["Repeated errors are evidence to investigate the design and conditions of use.", "Reduce the cause and support recovery rather than relying only on warnings or blame."], "keyPoints": ["Investigate systemic cause", "Prevent and recover"], "source": "Norman ch. 5 · Understanding Why There Is Error · Week 1 · PDF pp. 42–43, 59–61", "readingRef": "Norman ch. 5 · Understanding Why There Is Error", "lectureRef": "Week 1 · PDF pp. 42–43, 59–61", "book": "norman", "origin": "reading", "topic": "Human error", "level": "application"}, {"id": "w1-rs08", "group": "w1", "type": "short", "prompt": "Explain how usability and experience goals can interact.", "answer": ["Usability concerns task performance, while experience includes feelings such as satisfaction or frustration.", "Successful, understandable interaction can contribute to a better experience, so evaluate both together."], "keyPoints": ["Different emphasis", "Goals influence one another"], "source": "Interaction Design 6e · §1.9 · Week 1 · PDF pp. 70–78", "readingRef": "Interaction Design 6e · §1.9", "lectureRef": "Week 1 · PDF pp. 70–78", "book": "id", "origin": "reading", "topic": "Usability & UX", "level": "application"}, {"id": "w2-rs01", "group": "w2", "type": "short", "prompt": "A user sees “Pending” and assumes success. Identify the action-stage failure and a fix.", "answer": ["The user perceives the status but interprets its meaning incorrectly.", "Use clear wording that distinguishes waiting from completion and explains the next step."], "keyPoints": ["Perception versus interpretation", "Clarify status and next action"], "source": "Norman ch. 2 · The Seven Stages of Action · Week 2 · PDF pp. 13–14, 20", "readingRef": "Norman ch. 2 · The Seven Stages of Action", "lectureRef": "Week 2 · PDF pp. 13–14, 20", "book": "norman", "origin": "reading", "topic": "Action cycle", "level": "application"}, {"id": "w2-rs02", "group": "w2", "type": "short", "prompt": "Distinguish feedforward from feedback using a form.", "answer": ["Feedforward explains what an action will do, such as a clear “Book appointment” label.", "Feedback explains what happened, such as confirmation showing the booked details."], "keyPoints": ["Predict / choose action", "Understand result"], "source": "Norman ch. 2 · Seven Fundamental Design Principles · Week 2 · PDF pp. 13–14, 21–22", "readingRef": "Norman ch. 2 · Seven Fundamental Design Principles", "lectureRef": "Week 2 · PDF pp. 13–14, 21–22", "book": "norman", "origin": "reading", "topic": "Gulfs & action cycle", "level": "application"}, {"id": "w2-rs03", "group": "w2", "type": "short", "prompt": "Why can a checklist help a user resume after interruption?", "answer": ["It places information about remaining steps in the world rather than requiring recall.", "The user can inspect progress and continue without reconstructing every completed action."], "keyPoints": ["External memory support", "Resume from visible task state"], "source": "Norman ch. 3 · Knowledge in the Head and in the World · Week 2 · PDF pp. 26–29", "readingRef": "Norman ch. 3 · Knowledge in the Head and in the World", "lectureRef": "Week 2 · PDF pp. 26–29", "book": "norman", "origin": "reading", "topic": "External cognition", "level": "application"}, {"id": "w2-rs04", "group": "w2", "type": "short", "prompt": "A user thinks pressing an elevator button repeatedly speeds it up. Explain the issue.", "answer": ["The user’s mental model predicts an effect the system does not provide.", "Clear, consistent acknowledgement can help communicate that the request is already registered."], "keyPoints": ["Incorrect prediction", "Communicate actual behaviour"], "source": "Interaction Design 6e · §4.3.1; Norman ch. 1 · The System Image · Week 2 · PDF pp. 8–12, 15–23", "readingRef": "Interaction Design 6e · §4.3.1; Norman ch. 1 · The System Image", "lectureRef": "Week 2 · PDF pp. 8–12, 15–23", "book": "id", "origin": "reading", "topic": "Mental models", "level": "application"}, {"id": "w2-rs05", "group": "w2", "type": "short", "prompt": "Why should a menu not be judged solely by a seven-item memory limit?", "answer": ["Visible choices support recognition and search rather than recall of unseen items.", "Evaluate grouping, labels and actual task performance instead of imposing a universal item count."], "keyPoints": ["Recognition is different from recall", "Evaluate structure and task"], "source": "Interaction Design 6e · §4.2 · Memory · Week 2 · PDF pp. 142–146", "readingRef": "Interaction Design 6e · §4.2 · Memory", "lectureRef": "Week 2 · PDF pp. 142–146", "book": "id", "origin": "reading", "topic": "Memory", "level": "application"}, {"id": "w2-rs06", "group": "w2", "type": "short", "prompt": "Why can adding more animation make a critical update harder to notice?", "answer": ["Competing movement can capture attention and obscure what matters to the task.", "Use selective, relevant cues and a clear hierarchy instead of indiscriminate animation."], "keyPoints": ["Competing attention cues", "Selective salience and hierarchy"], "source": "Interaction Design 6e · §4.2 · Attention · Week 2 · PDF pp. 122–136", "readingRef": "Interaction Design 6e · §4.2 · Attention", "lectureRef": "Week 2 · PDF pp. 122–136", "book": "id", "origin": "reading", "topic": "Attention", "level": "application"}, {"id": "w2-rs07", "group": "w2", "type": "short", "prompt": "Relate a visible comparison diagram to external cognition.", "answer": ["The diagram makes relationships available to perception instead of requiring mental computation.", "This can reduce memory load and support reasoning about the comparison."], "keyPoints": ["External representation", "Offload computation / memory"], "source": "Interaction Design 6e · §4.3.5 · Week 2 · PDF pp. 26–36", "readingRef": "Interaction Design 6e · §4.3.5", "lectureRef": "Week 2 · PDF pp. 26–36", "book": "id", "origin": "reading", "topic": "External cognition", "level": "application"}, {"id": "w2-rs08", "group": "w2", "type": "short", "prompt": "Why might a skilled user select the wrong command after a toolbar changes?", "answer": ["A learned action sequence may run automatically using the previous layout.", "Preserve familiar mappings where appropriate and make necessary changes distinguishable."], "keyPoints": ["Automatic learned sequence", "Consistency / clear changes"], "source": "Norman ch. 5 · The Classification of Slips · Week 2 · PDF pp. 43–46", "readingRef": "Norman ch. 5 · The Classification of Slips", "lectureRef": "Week 2 · PDF pp. 43–46", "book": "norman", "origin": "reading", "topic": "Automatic processing", "level": "application"}, {"id": "w3-rs01", "group": "w3", "type": "short", "prompt": "Explain why touch can feel natural while still causing selection errors.", "answer": ["Direct touch acts on the target, reducing a separate pointer mapping.", "Small targets and finger occlusion can still reduce selection accuracy."], "keyPoints": ["Direct interaction benefit", "Precision and occlusion trade-off"], "source": "Interaction Design 6e · §7.2.10 · Week 3 · PDF pp. 5, 13, 48–52", "readingRef": "Interaction Design 6e · §7.2.10", "lectureRef": "Week 3 · PDF pp. 5, 13, 48–52", "book": "id", "origin": "reading", "topic": "Touch input", "level": "application"}, {"id": "w3-rs02", "group": "w3", "type": "short", "prompt": "A phone feature requires an undocumented gesture. Give a discoverability improvement.", "answer": ["The system supports the action but does not clearly signify how to perform it.", "Provide a visible cue or discoverable alternative control and test first-time use."], "keyPoints": ["Capability versus discoverability", "Clear cue / alternative"], "source": "Norman ch. 1 · Signifiers; Interaction Design 6e · §7.2.10 · Week 1 · PDF p. 81; Week 3 pp. 51–52", "readingRef": "Norman ch. 1 · Signifiers; Interaction Design 6e · §7.2.10", "lectureRef": "Week 1 · PDF p. 81; Week 3 pp. 51–52", "book": "norman", "origin": "reading", "topic": "Discoverability", "level": "application"}, {"id": "w3-rs03", "group": "w3", "type": "short", "prompt": "Why should a desktop interface’s hover interaction be reconsidered on mobile?", "answer": ["Touch use may not offer the same hover mechanism as a mouse pointer.", "Make essential information and actions accessible through supported touch interactions."], "keyPoints": ["Different input mechanisms", "Accessible touch alternative"], "source": "Interaction Design 6e · §7.2.6–7.2.10 · Week 3 · PDF pp. 51–52, 64", "readingRef": "Interaction Design 6e · §7.2.6–7.2.10", "lectureRef": "Week 3 · PDF pp. 51–52, 64", "book": "id", "origin": "reading", "topic": "Mobile adaptation", "level": "application"}, {"id": "w3-rs04", "group": "w3", "type": "short", "prompt": "Give a task-based reason to prefer a pen for freehand input.", "answer": ["A pen can capitalize on familiar drawing skills and precise contact.", "Choose it when those benefits fit the task, rather than assuming every new device is superior."], "keyPoints": ["Match practised skill / precision", "Task-dependent choice"], "source": "Interaction Design 6e · §7.2.9 · Week 3 · PDF pp. 2–5, 13", "readingRef": "Interaction Design 6e · §7.2.9", "lectureRef": "Week 3 · PDF pp. 2–5, 13", "book": "id", "origin": "reading", "topic": "Device selection", "level": "application"}, {"id": "w3-rs05", "group": "w3", "type": "short", "prompt": "A voice interface mishears a request. What should recovery support?", "answer": ["Explain what was understood or unclear and allow correction.", "Provide a way to retry, return or use another suitable input method."], "keyPoints": ["Clear feedback / clarification", "User recovery and control"], "source": "Interaction Design 6e · §7.2.8 · Week 3 · PDF pp. 26–27; Week 1 pp. 88–90", "readingRef": "Interaction Design 6e · §7.2.8", "lectureRef": "Week 3 · PDF pp. 26–27; Week 1 pp. 88–90", "book": "id", "origin": "reading", "topic": "Voice feedback", "level": "application"}, {"id": "w3-rs06", "group": "w3", "type": "short", "prompt": "Why should haptic feedback be selective rather than continuous?", "answer": ["Persistent vibration can annoy users or become something they ignore.", "Use meaningful patterns at appropriate moments and support user control."], "keyPoints": ["Annoyance / habituation", "Relevant controlled feedback"], "source": "Interaction Design 6e · §7.2.12 · Week 3 · PDF p. 25; Week 2 pp. 123, 133–136", "readingRef": "Interaction Design 6e · §7.2.12", "lectureRef": "Week 3 · PDF p. 25; Week 2 pp. 123, 133–136", "book": "id", "origin": "reading", "topic": "Haptics & attention", "level": "application"}, {"id": "w3-rs07", "group": "w3", "type": "short", "prompt": "Explain why copying desktop status corners into VR can be poor design.", "answer": ["Monitoring distant corners can be uncomfortable in an immersive view.", "Test feedback near relevant objects while accounting for movement, comfort and safety."], "keyPoints": ["Viewing discomfort", "Task-relevant feedback placement"], "source": "Interaction Design 6e · §7.2.4 · Week 3 · PDF pp. 30–35", "readingRef": "Interaction Design 6e · §7.2.4", "lectureRef": "Week 3 · PDF pp. 30–35", "book": "id", "origin": "reading", "topic": "Virtual reality", "level": "application"}, {"id": "w3-rs08", "group": "w3", "type": "short", "prompt": "Why should a location-aware mobile app let users control alerts?", "answer": ["Detecting location does not establish that every interruption is useful or welcome.", "Let users choose relevant notifications and pause them when their context changes."], "keyPoints": ["Capability does not prove relevance", "Control interruptions"], "source": "Interaction Design 6e · §7.2.6 · Week 3 · PDF pp. 20, 55–56", "readingRef": "Interaction Design 6e · §7.2.6", "lectureRef": "Week 3 · PDF pp. 20, 55–56", "book": "id", "origin": "reading", "topic": "Mobile notifications", "level": "application"}, {"id": "w4-rs01", "group": "w4", "type": "short", "prompt": "A client demands a button before describing the problem. What should the designer investigate?", "answer": ["Identify the user’s underlying goal and current difficulty before choosing a solution.", "Observe or ask about concrete activity, then compare ways of supporting that goal."], "keyPoints": ["Goal before feature", "Evidence and alternative solutions"], "source": "Norman ch. 6 · Solving the Correct Problem · Week 4 · PDF pp. 23–26", "readingRef": "Norman ch. 6 · Solving the Correct Problem", "lectureRef": "Week 4 · PDF pp. 23–26", "book": "norman", "origin": "reading", "topic": "Requirements discovery", "level": "application"}, {"id": "w4-rs02", "group": "w4", "type": "short", "prompt": "Turn “our interface is easy to learn” into an assessable requirement.", "answer": ["Specify the intended user group and a representative task.", "Set a measurable success criterion, such as completion without help within a chosen time."], "keyPoints": ["User and task specified", "Measurable criterion"], "source": "Interaction Design 6e · §11.2.2–11.3 · Week 4 · PDF pp. 8, 17", "readingRef": "Interaction Design 6e · §11.2.2–11.3", "lectureRef": "Week 4 · PDF pp. 8, 17", "book": "id", "origin": "reading", "topic": "Measurable requirements", "level": "application"}, {"id": "w4-rs03", "group": "w4", "type": "short", "prompt": "Explain why the same job title is not enough to define a persona.", "answer": ["People in the same role can have different goals, experience and work practices.", "Build personas from relevant research patterns rather than job titles or convenient stereotypes."], "keyPoints": ["Meaningful user differences", "Research-based synthesis"], "source": "Interaction Design 6e · §11.5.1 · Week 4 · PDF pp. 66–67", "readingRef": "Interaction Design 6e · §11.5.1", "lectureRef": "Week 4 · PDF pp. 66–67", "book": "id", "origin": "reading", "topic": "Personas", "level": "application"}, {"id": "w4-rs04", "group": "w4", "type": "short", "prompt": "Why pilot a questionnaire or interview guide?", "answer": ["A pilot can reveal unclear questions and problems in the procedure.", "Revise those problems before gathering the main study’s data."], "keyPoints": ["Find question / procedural issues", "Revise before main study"], "source": "Interaction Design 6e · §8.2.6 · Week 4 · PDF pp. 33, 39–43, 61", "readingRef": "Interaction Design 6e · §8.2.6", "lectureRef": "Week 4 · PDF pp. 33, 39–43, 61", "book": "id", "origin": "reading", "topic": "Research design", "level": "application"}, {"id": "w4-rs05", "group": "w4", "type": "short", "prompt": "Survey categories overlap at age 25. Explain the problem and fix.", "answer": ["A 25-year-old cannot determine which of the two categories to choose.", "Use non-overlapping ranges that cover the population relevant to the study."], "keyPoints": ["Ambiguous overlap", "Non-overlapping relevant categories"], "source": "Interaction Design 6e · §8.5.2 · Week 4 · PDF pp. 40–43", "readingRef": "Interaction Design 6e · §8.5.2", "lectureRef": "Week 4 · PDF pp. 40–43", "book": "id", "origin": "reading", "topic": "Questionnaire design", "level": "application"}, {"id": "w4-rs06", "group": "w4", "type": "short", "prompt": "Interviews suggest success, but observed tasks show errors. What should you conclude?", "answer": ["The evidence sources disagree, so investigate what each actually measures.", "Compare reported experience with observed performance rather than treating one as automatic proof."], "keyPoints": ["Different evidence / measures", "Investigate using triangulation"], "source": "Interaction Design 6e · §8.2.5 · Week 4 · PDF pp. 46–49, 61", "readingRef": "Interaction Design 6e · §8.2.5", "lectureRef": "Week 4 · PDF pp. 46–49, 61", "book": "id", "origin": "reading", "topic": "Triangulation", "level": "application"}, {"id": "w4-rs07", "group": "w4", "type": "short", "prompt": "Why should a use case include an invalid-entry path?", "answer": ["The successful path alone does not specify what happens when input fails.", "Describe the error response and how the user can correct it and continue."], "keyPoints": ["Success path is incomplete", "Specify error and recovery"], "source": "Interaction Design 6e · §11.6 · Week 4 · PDF pp. 70–75", "readingRef": "Interaction Design 6e · §11.6", "lectureRef": "Week 4 · PDF pp. 70–75", "book": "id", "origin": "reading", "topic": "Use cases", "level": "application"}, {"id": "w4-rs08", "group": "w4", "type": "short", "prompt": "Why can task analysis include paper notes and other offline actions?", "answer": ["The user’s goal may depend on activity beyond the software interface.", "Include relevant observable actions and artifacts to understand the complete task."], "keyPoints": ["Goal extends beyond interface", "Relevant actions and artifacts"], "source": "Interaction Design 6e · §11.4; Norman ch. 6 · Observation · Week 4 · PDF pp. 76–79", "readingRef": "Interaction Design 6e · §11.4; Norman ch. 6 · Observation", "lectureRef": "Week 4 · PDF pp. 76–79", "book": "id", "origin": "reading", "topic": "Task analysis", "level": "application"}]};
